//! Phase B (valid-path) + Phase C (error-path) differential tests for the
//! **Sequence API** of `compress/zstd_compress.c`:
//!
//!   * `ZSTD_sequenceBound`                        (zstd_compress.c:3513)
//!   * `ZSTD_generateSequences`                    (zstd_compress.c:3520)
//!   * `ZSTD_mergeBlockDelimiters`                 (zstd_compress.c:3555)
//!   * `ZSTD_compressSequences`                    (zstd_compress.c:7063)
//!   * `ZSTD_compressSequencesAndLiterals`         (zstd_compress.c:7585)
//!   * `ZSTD_registerSequenceProducer`             (zstd_compress.c:7819)
//!   * `ZSTD_CCtxParams_registerSequenceProducer`  (zstd_compress.c:7830)
//!
//! Everything runs through `diff` / `diff_bytes`, i.e. the identical call
//! sequence is replayed against the C `.so` and the Rust `.so` and *every*
//! observable is compared: the return code (symbolically, via `R`), every
//! produced `ZSTD_Sequence` field, and the whole destination buffer including
//! the bytes the callee never wrote.
#![allow(non_snake_case)]
#![allow(non_upper_case_globals)]
mod common;
use common::*;
use std::ffi::{c_int, c_uint, c_void};

// ---------------------------------------------------------------------------
// Constants from the C headers
// ---------------------------------------------------------------------------

/// `zstd.h:1276`
const ZSTD_MINMATCH_MIN: c_int = 3;
/// `zstd.h:1275`
const ZSTD_MINMATCH_MAX: c_int = 7;
/// `zstd.h:1281` — the divisor `ZSTD_sequenceBound` uses for delimiters.
const ZSTD_BLOCKSIZE_MAX_MIN: usize = 1 << 10;
/// `ZSTD_SEQUENCE_PRODUCER_ERROR` (`zstd.h:2928`)
const ZSTD_SEQUENCE_PRODUCER_ERROR: SizeT = SizeT::MAX;

// ---------------------------------------------------------------------------
// Signatures
// ---------------------------------------------------------------------------

type FnSequenceBound = unsafe extern "C" fn(SizeT) -> SizeT;
type FnGenerateSequences =
    unsafe extern "C" fn(*mut c_void, *mut ZSTD_Sequence, SizeT, *const c_void, SizeT) -> SizeT;
type FnMergeBlockDelimiters = unsafe extern "C" fn(*mut ZSTD_Sequence, SizeT) -> SizeT;
type FnCompressSequences = unsafe extern "C" fn(
    *mut c_void,
    *mut c_void,
    SizeT,
    *const ZSTD_Sequence,
    SizeT,
    *const c_void,
    SizeT,
) -> SizeT;
type FnCompressSequencesAndLiterals = unsafe extern "C" fn(
    *mut c_void,
    *mut c_void,
    SizeT,
    *const ZSTD_Sequence,
    SizeT,
    *const c_void,
    SizeT,
    SizeT,
    SizeT,
) -> SizeT;

/// `ZSTD_sequenceProducer_F` (`zstd.h:2930`)
type SeqProdF = unsafe extern "C" fn(
    *mut c_void,
    *mut ZSTD_Sequence,
    SizeT,
    *const c_void,
    SizeT,
    *const c_void,
    SizeT,
    c_int,
    SizeT,
) -> SizeT;
type FnRegisterSequenceProducer =
    unsafe extern "C" fn(*mut c_void, *mut c_void, Option<SeqProdF>);

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

fn seq_bound(l: &Lib, n: usize) -> usize {
    let f = l.sym::<FnSequenceBound>("ZSTD_sequenceBound");
    unsafe { f(n) }
}

/// Set a list of `(param, value)` on a fresh CCtx; returns the first failure.
fn set_params(l: &Lib, ctx: &Ctx<'_>, params: &[(c_int, c_int)]) -> Option<R> {
    let set = l.sym::<FnCCtxSetParameter>("ZSTD_CCtx_setParameter");
    for (p, v) in params {
        let rc = unsafe { set(ctx.ptr, *p, *v) };
        if is_error(l, rc) {
            return Some(res(l, rc));
        }
    }
    None
}

/// `ZSTD_generateSequences` on a fresh CCtx configured with `params`.
/// Returns the status plus the *entire* out-sequence array (poisoned first, so
/// entries the C never wrote are compared too).
fn gen_seqs(l: &Lib, params: &[(c_int, c_int)], src: &[u8], cap: usize) -> (R, Seqs) {
    let ctx = Ctx::cctx(l);
    if let Some(e) = set_params(l, &ctx, params) {
        return (e, Seqs(Vec::new()));
    }
    // 0xEE poison: any field the callee leaves untouched shows up in the diff.
    let mut out = vec![
        ZSTD_Sequence {
            offset: 0xEEEE_EEEE,
            litLength: 0xEEEE_EEEE,
            matchLength: 0xEEEE_EEEE,
            rep: 0xEEEE_EEEE,
        };
        cap
    ];
    let f = l.sym::<FnGenerateSequences>("ZSTD_generateSequences");
    let n = unsafe {
        f(
            ctx.ptr,
            out.as_mut_ptr(),
            cap,
            src.as_ptr() as *const c_void,
            src.len(),
        )
    };
    let r = res(l, n);
    if let R::Ok(n) = r {
        // On success only the first `n` entries are meaningful.  On *failure*
        // the whole poisoned buffer is compared, which pins any partial write.
        out.truncate(n);
    }
    (r, Seqs(out))
}

/// A **fixture** sequence array for `src`: generated by `ZSTD_generateSequences`
/// with both libraries (so the fixture itself is differentially checked) and
/// returned only when it succeeded.
///
/// `ZSTD_generateSequences` legitimately fails for some inputs — in particular
/// whenever any block is shorter than 7 bytes
/// (`MIN_CBLOCK_SIZE+ZSTD_blockHeaderSize+1+1`), which happens for
/// `srcSize == 131073` because the trailing block is a single byte, so
/// `ZSTD_buildSeqStore` reports `ZSTDbss_noCompress` and zstd_compress.c:4402
/// turns that into `sequenceProducer_failed`. Those inputs yield `None`, and the
/// caller skips them; the *agreement* on the failure has already been asserted.
fn gen_fixture(label: &str, params: &[(c_int, c_int)], src: &[u8]) -> Option<Vec<ZSTD_Sequence>> {
    let cap = seq_bound(&pair().c, src.len());
    let (r, v) = diff(&format!("fixture/{label}"), |l| gen_seqs(l, params, src, cap));
    match r {
        R::Ok(_) => Some(v.0),
        R::Err(..) => None,
    }
}

/// A sequence array whose `Debug` stays readable even for 100 000 entries:
/// length, FNV-1a digest over the raw little-endian fields, and a head/tail
/// sample. Equality is still over the *whole* array, every field.
#[derive(Clone, PartialEq, Eq)]
struct Seqs(Vec<ZSTD_Sequence>);

impl Seqs {
    fn raw(&self) -> Vec<u8> {
        let mut v = Vec::with_capacity(self.0.len() * 16);
        for s in &self.0 {
            v.extend_from_slice(&s.offset.to_le_bytes());
            v.extend_from_slice(&s.litLength.to_le_bytes());
            v.extend_from_slice(&s.matchLength.to_le_bytes());
            v.extend_from_slice(&s.rep.to_le_bytes());
        }
        v
    }
}

impl std::fmt::Debug for Seqs {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let one = |s: &ZSTD_Sequence| {
            format!("(of:{} ll:{} ml:{} rep:{})", s.offset, s.litLength, s.matchLength, s.rep)
        };
        write!(f, "Seqs{{n={},fnv=0x{:016x}", self.0.len(), fnv1a64(&self.raw()))?;
        if self.0.len() <= 20 {
            for s in &self.0 {
                write!(f, ",{}", one(s))?;
            }
        } else {
            for s in &self.0[..10] {
                write!(f, ",{}", one(s))?;
            }
            write!(f, ",..")?;
            for s in &self.0[self.0.len() - 4..] {
                write!(f, ",{}", one(s))?;
            }
        }
        write!(f, "}}")
    }
}

// ===========================================================================
// STEP 1 — ZSTD_sequenceBound
// ===========================================================================

/// `ZSTD_sequenceBound` (zstd_compress.c:3513):
/// `(srcSize/ZSTD_MINMATCH_MIN + 1) + (srcSize/ZSTD_BLOCKSIZE_MAX_MIN + 1)`.
/// Pure integer division, no error path — so the only thing that can diverge is
/// the arithmetic itself, including at the 128 KB block boundaries.
#[test]
fn t01_sequence_bound() {
    covers(&["CFG:183"]);
    let sizes: &[usize] = &[
        0,
        1,
        2,
        3,
        4,
        5,
        6,
        7,
        8,
        100,
        1023,
        1024,
        1025,
        131071,
        131072,
        131073,
        1 << 20,
        10 * (1 << 20),
    ];
    for &n in sizes {
        let got = diff(&format!("sequenceBound({n})"), |l| seq_bound(l, n));
        // Cross-check against the documented formula so a *matching* pair of
        // wrong implementations still fails.
        let want = (n / ZSTD_MINMATCH_MIN as usize + 1) + (n / ZSTD_BLOCKSIZE_MAX_MIN + 1);
        assert_eq!(got, want, "sequenceBound({n}) formula mismatch");
    }
}

// ===========================================================================
// STEP 2 — ZSTD_generateSequences
// ===========================================================================

/// The (corpus, size) grid STEP 2 walks. The sizes straddle the
/// `ZSTDbss_noCompress` cut-off (`srcSize < 7`), the 1/2/4-byte
/// frame-content-size encodings and the 128 KB block boundary.
const GEN_SIZES: &[usize] = &[0, 1, 6, 7, 8, 100, 1024, 65536, 131072, 131073, 300000];

/// `ZSTD_generateSequences` (zstd_compress.c:3520) over every corpus shape and
/// every interesting size at default parameters.
///
/// `srcSize < 7` makes `ZSTD_buildSeqStore` return `ZSTDbss_noCompress`, and
/// with `seqCollector.collectSequences` set that is turned into
/// `ERROR(sequenceProducer_failed)` (106) at zstd_compress.c:4402 — the
/// documented "it will give up and fail" case. Incompressible 64 KB blocks
/// reach the same site.
#[test]
fn t02_generate_sequences_corpora_sizes() {
    covers(&[
        "CFG:186",
        "ERR:compress/zstd_compress.c:4402",
        "ERR:compress/zstd_compress.c:3445",
    ]);
    for &kind in ALL_CORPORA {
        for &n in GEN_SIZES {
            let src = corpus(kind, n, 0x5EED_0001);
            let cap = seq_bound(&pair().c, n);
            diff(&format!("gen/{kind:?}/n={n}/cap=bound"), |l| {
                gen_seqs(l, &[(ZSTD_c_compressionLevel, 3)], &src, cap)
            });
        }
    }
}

/// `ZSTD_generateSequences` across the whole governing parameter grid:
/// `ZSTD_c_compressionLevel` (which selects the strategy and therefore the
/// match finder feeding `ZSTD_copyBlockSequences`), the full valid
/// `ZSTD_c_minMatch` range 3..=7 (`ZSTD_MINMATCH_MIN`..`ZSTD_MINMATCH_MAX`,
/// also the divisor of `seqStore.maxNbSeq`), and `ZSTD_c_windowLog` (which
/// bounds the offsets that can appear).
#[test]
fn t03_generate_sequences_param_grid() {
    covers(&["CFG:185-186", "ERR:compress/zstd_compress.c:3445"]);
    // A fixed rotation of (corpus, size) pairs so every parameter combination
    // sees several data shapes without exploding the cross product.
    let shapes: &[(Corpus, usize)] = &[
        (Corpus::Text, 100),
        (Corpus::LongRepeats, 8192),
        (Corpus::Random, 65536),
        (Corpus::Periodic, 1024),
        (Corpus::Zeros, 131073),
        (Corpus::Mixed, 20000),
        (Corpus::Counter, 4096),
        (Corpus::SmallAlphabet, 40000),
        (Corpus::Sparse, 70000),
        (Corpus::OneByte, 200000),
    ];
    let mut k = 0usize;
    for &level in &[-5i32, 1, 3, 9, 19, 22] {
        for mm in ZSTD_MINMATCH_MIN..=ZSTD_MINMATCH_MAX {
            for &wlog in &[10i32, 17, 22] {
                for _ in 0..2 {
                    let (kind, n) = shapes[k % shapes.len()];
                    k += 1;
                    // High levels on the biggest inputs are the slow corner;
                    // keep the suite inside its time budget by capping there.
                    let n = if level >= 19 { n.min(20000) } else { n };
                    let src = corpus(kind, n, 0x5EED_0002);
                    let cap = seq_bound(&pair().c, n);
                    let params = [
                        (ZSTD_c_compressionLevel, level),
                        (ZSTD_c_minMatch, mm),
                        (ZSTD_c_windowLog, wlog),
                    ];
                    diff(
                        &format!("gen/lvl={level}/mm={mm}/wlog={wlog}/{kind:?}/n={n}"),
                        |l| gen_seqs(l, &params, &src, cap),
                    );
                }
            }
        }
    }
}

/// `outSeqsCapacity` sweep. The capacity lands in `seqCollector.maxSequences`
/// and `ZSTD_copyBlockSequences` (zstd_compress.c:3445) returns
/// `ERROR(dstSize_tooSmall)` (70) when
/// `nbInSequences + 1 > maxSequences - seqIndex`; the error is then forwarded
/// out of `ZSTD_compress2` at zstd_compress.c:3549. Capacity 0 is the extreme
/// of that (and the C must not write a single entry).
#[test]
fn t04_generate_sequences_capacity() {
    covers(&[
        "CFG:185",
        "ERR:compress/zstd_compress.c:3445", "ERR:compress/zstd_compress.c:3549",
    ]);
    for &kind in &[Corpus::Text, Corpus::LongRepeats, Corpus::Periodic, Corpus::Random] {
        for &n in &[7usize, 100, 1024, 65536, 131073, 300000] {
            let src = corpus(kind, n, 0x5EED_0003);
            let bound = seq_bound(&pair().c, n);
            // How many the level actually produces, so "exact" and "exact-1"
            // straddle the real requirement rather than the pessimistic bound.
            let exact = match gen_seqs(&pair().c, &[(ZSTD_c_compressionLevel, 3)], &src, bound).0 {
                R::Ok(v) => v,
                R::Err(..) => 0,
            };
            let mut caps = vec![bound, bound.saturating_sub(1), 0, 1];
            if exact > 0 {
                caps.push(exact);
                caps.push(exact - 1);
                caps.push(exact + 1);
            }
            for cap in caps {
                diff(&format!("gencap/{kind:?}/n={n}/cap={cap}"), |l| {
                    gen_seqs(l, &[(ZSTD_c_compressionLevel, 3)], &src, cap)
                });
            }
        }
    }
}

/// `ZSTD_generateSequences` refuses two parameters outright, reading them back
/// with `ZSTD_CCtx_getParameter` in a fixed order — `ZSTD_c_targetCBlockSize`
/// (zstd_compress.c:3529) before `ZSTD_c_nbWorkers` (zstd_compress.c:3534),
/// both `ERROR(parameter_unsupported)` (40). `nbWorkers` can never become
/// non-zero in a build without `ZSTD_MULTITHREAD`, so this pins that
/// `setParameter` rejection as well.
#[test]
fn t05_generate_sequences_unsupported_params() {
    covers(&[
        "CFG:184",
        "ERR:compress/zstd_compress.c:3529", "ERR:compress/zstd_compress.c:3534",
    ]);
    let src = corpus(Corpus::Text, 65536, 0x5EED_0004);
    let bound = seq_bound(&pair().c, src.len());
    for &tcbs in &[0i32, 1340, 2048, 131072] {
        for &nbw in &[0i32, 1, 4] {
            let params = [(ZSTD_c_targetCBlockSize, tcbs), (ZSTD_c_nbWorkers, nbw)];
            diff(&format!("gen/tcbs={tcbs}/nbWorkers={nbw}"), |l| {
                gen_seqs(l, &params, &src, bound)
            });
        }
    }
}

// ===========================================================================
// STEP 3 — ZSTD_mergeBlockDelimiters
// ===========================================================================

/// `ZSTD_mergeBlockDelimiters` (zstd_compress.c:3555) in place on a private copy
/// per library. Returns the new count plus the WHOLE array as it was left,
/// including the tail entries past the returned count that the C never rewrote.
fn merge_delims(l: &Lib, seqs: &[ZSTD_Sequence]) -> (R, Seqs) {
    let mut v = seqs.to_vec();
    let f = l.sym::<FnMergeBlockDelimiters>("ZSTD_mergeBlockDelimiters");
    let n = unsafe { f(v.as_mut_ptr(), v.len()) };
    (res(l, n), Seqs(v))
}

/// `ZSTD_mergeBlockDelimiters` on real `ZSTD_generateSequences` output (which
/// always uses explicit block delimiters) plus the hand-built shapes the loop
/// special-cases: a TRAILING delimiter (whose `litLength` is silently dropped,
/// because the fold into `sequences[in+1]` is guarded by `in != seqsSize-1`),
/// purely interior delimiters, a delimiter-only array, and back-to-back
/// delimiters (whose litLengths accumulate through the chain).
#[test]
fn t06_merge_block_delimiters() {
    covers(&["CFG:187"]);
    // (a) real generator output across shapes and sizes.
    for &kind in ALL_CORPORA {
        for &n in &[7usize, 100, 1024, 65536, 131072, 131073, 300000] {
            let src = corpus(kind, n, 0x5EED_0011);
            let lbl = format!("merge/{kind:?}/n={n}");
            let Some(seqs) = gen_fixture(&lbl, &[(ZSTD_c_compressionLevel, 3)], &src) else {
                continue;
            };
            diff(&lbl, |l| merge_delims(l, &seqs));
        }
    }

    // (b) hand-built arrays exercising the loop's corner cases.
    let d = |ll: c_uint| ZSTD_Sequence { offset: 0, litLength: ll, matchLength: 0, rep: 0 };
    let s = |of: c_uint, ll: c_uint, ml: c_uint| ZSTD_Sequence {
        offset: of,
        litLength: ll,
        matchLength: ml,
        rep: 0,
    };
    let cases: Vec<(&str, Vec<ZSTD_Sequence>)> = vec![
        ("empty", vec![]),
        ("only-delim-ll0", vec![d(0)]),
        ("only-delim-ll7", vec![d(7)]),
        ("two-delims", vec![d(3), d(4)]),
        ("trailing-delim", vec![s(1, 2, 5), d(9)]),
        ("interior-delim", vec![s(1, 2, 5), d(9), s(2, 1, 4)]),
        ("leading-delim", vec![d(5), s(1, 2, 5)]),
        (
            "chain-of-delims",
            vec![d(1), d(2), d(3), s(4, 100, 8), d(6)],
        ),
        ("no-delim-at-all", vec![s(1, 2, 5), s(2, 3, 6), s(3, 4, 7)]),
        // offset == 0 but matchLength != 0 is NOT a delimiter for this function
        // (the guard is `offset == 0 && matchLength == 0`).
        ("of0-ml5", vec![s(0, 2, 5), d(1)]),
        // matchLength == 0 but offset != 0 is likewise not a delimiter.
        ("of1-ml0", vec![s(1, 2, 0), d(1)]),
        (
            "ll-overflow-fold",
            vec![d(0xFFFF_FFFF), s(1, 2, 5), d(0)],
        ),
    ];
    for (name, v) in cases {
        diff(&format!("merge/hand/{name}"), |l| merge_delims(l, &v));
    }

    // (c) merging twice must be idempotent in the sense that the second pass
    // finds nothing left to merge (the output has no delimiters at all).
    let src = corpus(Corpus::Text, 300000, 0x5EED_0012);
    let seqs = gen_fixture("merge/twice", &[(ZSTD_c_compressionLevel, 3)], &src).unwrap();
    let merged = diff("merge/twice/pass1", |l| merge_delims(l, &seqs));
    let once = merged.1 .0[..match merged.0 {
        R::Ok(n) => n,
        R::Err(..) => 0,
    }]
        .to_vec();
    diff("merge/twice/pass2", |l| merge_delims(l, &once));
}

// ===========================================================================
// STEP 4 — ZSTD_compressSequences, valid path
// ===========================================================================

/// One `ZSTD_compressSequences` call on a fresh CCtx. `dst` is poisoned with
/// 0xCD and the WHOLE buffer is returned, so bytes the callee wrote past the
/// returned size (entropy-coder scratch that a later raw/RLE block overwrote,
/// for example) are compared too.
fn compress_seqs(
    l: &Lib,
    params: &[(c_int, c_int)],
    seqs: &[ZSTD_Sequence],
    src: &[u8],
    cap: usize,
) -> (R, Blob) {
    let ctx = Ctx::cctx(l);
    if let Some(e) = set_params(l, &ctx, params) {
        return (e, Blob(Vec::new()));
    }
    let mut dst = vec![0xCDu8; cap];
    let f = l.sym::<FnCompressSequences>("ZSTD_compressSequences");
    let n = unsafe {
        f(
            ctx.ptr,
            dst.as_mut_ptr() as *mut c_void,
            cap,
            seqs.as_ptr(),
            seqs.len(),
            src.as_ptr() as *const c_void,
            src.len(),
        )
    };
    (res(l, n), Blob(dst))
}

/// Decompress `frame` with both libraries and require the original bytes back.
fn roundtrip(label: &str, frame: &[u8], want: &[u8]) {
    let got = diff_bytes(&format!("rt/{label}"), |l| {
        decompress_simple(l, frame, want.len().max(1))
    });
    assert_eq!(got.0, R::Ok(want.len()), "rt/{label}: decompressed size");
    assert_eq!(&got.1 .0[..], want, "rt/{label}: content mismatch");
}

/// The valid-path parameter matrix of `ZSTD_compressSequences`
/// (zstd_compress.c:7063).
///
/// * `ZSTD_c_blockDelimiters` picks the sequence copier in
///   `ZSTD_selectSequenceCopier` (zstd_compress.c:6881):
///   `ZSTD_transferSequences_wBlockDelim` vs `_noDelim`, and `determine_blockSize`
///   switches between `blockSize_explicitDelimiter` and `MIN(remaining, blockSizeMax)`.
///   In `noBlockDelimiters` mode the array must first be run through
///   `ZSTD_mergeBlockDelimiters`.
/// * `ZSTD_c_validateSequences` turns `ZSTD_validateSequence` on. Because the
///   header documents that value 0 "blindly accepts the Sequences provided.
///   Invalid Sequences cause undefined behavior", value 0 is only ever fed
///   sequences that `ZSTD_generateSequences` produced for that exact input and
///   those exact parameters.
/// * `ZSTD_c_repcodeResolution` selects `OFFSET_TO_OFFBASE` + the three-way
///   rep[] back-patch (`ps_disable`) or `ZSTD_finalizeOffBase` + `ZSTD_updateRep`
///   per sequence (`ps_enable`); `ps_auto` resolves to
///   `cLevel < 10 ? ps_disable : ps_enable`.
/// * `ZSTD_c_minMatch` also sizes `seqStore.maxNbSeq`.
#[test]
fn t07_compress_sequences_valid_matrix() {
    covers(&[
        "CFG:188-189",
        "CFG:146",
        "CFG:198",
        "ERR:compress/zstd_compress.c:6690", "ERR:compress/zstd_compress.c:6844",
    ]);
    let shapes: &[(Corpus, usize)] = &[
        (Corpus::Text, 20000),
        (Corpus::LongRepeats, 65536),
        (Corpus::Periodic, 1024),
        (Corpus::Random, 8192),
        (Corpus::Zeros, 40000),
        (Corpus::Mixed, 12345),
        (Corpus::SmallAlphabet, 100),
        (Corpus::Counter, 3000),
        (Corpus::Sparse, 50000),
        (Corpus::OneByte, 7),
    ];
    let levels: &[c_int] = &[1, 3, 9, 10, 19];
    let mut k = 0usize;
    for &delims in &[ZSTD_sf_noBlockDelimiters, ZSTD_sf_explicitBlockDelimiters] {
        for &validate in &[0i32, 1] {
            for &repres in &[ZSTD_ps_auto, ZSTD_ps_enable, ZSTD_ps_disable] {
                for mm in ZSTD_MINMATCH_MIN..=ZSTD_MINMATCH_MAX {
                    for _ in 0..3 {
                        let (kind, n) = shapes[k % shapes.len()];
                        let level = levels[k % levels.len()];
                        let tcbs = if k % 2 == 0 { 0 } else { 2048 };
                        k += 1;
                        let src = corpus(kind, n, 0x5EED_0021);
                        // The fixture is generated with the SAME cParams it will
                        // be compressed with, so every match is >= minMatch and
                        // every offset within the window: the parse is valid by
                        // construction, which is what validateSequences == 0
                        // requires.
                        let gp = [(ZSTD_c_compressionLevel, level), (ZSTD_c_minMatch, mm)];
                        let lbl = format!(
                            "cs/d={delims}/v={validate}/r={repres}/mm={mm}/lvl={level}/tcbs={tcbs}/{kind:?}/n={n}"
                        );
                        let Some(mut seqs) = gen_fixture(&lbl, &gp, &src) else {
                            continue;
                        };
                        if delims == ZSTD_sf_noBlockDelimiters {
                            // ZSTD_generateSequences always emits explicit
                            // delimiters; fold them away for noDelim mode.
                            let n = match merge_delims(&pair().c, &seqs).0 {
                                R::Ok(n) => n,
                                R::Err(c, s) => panic!("merge failed {c}:{s}"),
                            };
                            let mut m = merge_delims(&pair().c, &seqs).1 .0;
                            m.truncate(n);
                            seqs = m;
                        }
                        let params = [
                            (ZSTD_c_compressionLevel, level),
                            (ZSTD_c_minMatch, mm),
                            (ZSTD_c_blockDelimiters, delims),
                            (ZSTD_c_validateSequences, validate),
                            (ZSTD_c_repcodeResolution, repres),
                            (ZSTD_c_targetCBlockSize, tcbs),
                        ];
                        let cap = compress_bound(&pair().c, n).max(64);
                        let (r, frame) = diff_bytes(&lbl, |l| {
                            compress_seqs(l, &params, &seqs, &src, cap)
                        });
                        if let R::Ok(cs) = r {
                            roundtrip(&lbl, &frame.0[..cs], &src);
                        }
                    }
                }
            }
        }
    }
}

/// The two documented end-to-end recipes on a multi-block (300 KB) input:
/// explicit delimiters straight from `ZSTD_generateSequences` (CONFIGS row 188)
/// and merged sequences with `ZSTD_sf_noBlockDelimiters` (row 189, which is the
/// only way to exercise `ZSTD_transferSequences_noDelim`'s match-splitting at a
/// real block boundary). Also with `ZSTD_c_checksumFlag` (row 199), whose 4-byte
/// trailer is written by `ZSTD_compressSequences` itself.
#[test]
fn t08_compress_sequences_multiblock_roundtrip() {
    covers(&["CFG:188-189", "CFG:199", "ERR:compress/zstd_compress.c:7102"]);
    for &kind in &[Corpus::Text, Corpus::LongRepeats, Corpus::Periodic, Corpus::Sparse] {
        for &n in &[131072usize, 300000, 400000] {
            for &level in &[3i32, 19] {
                for &checksum in &[0i32, 1] {
                    let src = corpus(kind, n, 0x5EED_0022);
                    let gp = [(ZSTD_c_compressionLevel, level)];
                    let base = format!("csmb/{kind:?}/n={n}/lvl={level}/ck={checksum}");
                    let Some(seqs) = gen_fixture(&base, &gp, &src) else {
                        continue;
                    };
                    let cap = compress_bound(&pair().c, n);
                    // explicit delimiters
                    let p1 = [
                        (ZSTD_c_compressionLevel, level),
                        (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                        (ZSTD_c_validateSequences, 1),
                        (ZSTD_c_checksumFlag, checksum),
                    ];
                    let (r, f1) = diff_bytes(&format!("{base}/explicit"), |l| {
                        compress_seqs(l, &p1, &seqs, &src, cap)
                    });
                    if let R::Ok(cs) = r {
                        roundtrip(&format!("{base}/explicit"), &f1.0[..cs], &src);
                    }
                    // merged + noBlockDelimiters
                    let mut merged = seqs.clone();
                    let mn = match merge_delims(&pair().c, &merged).0 {
                        R::Ok(v) => v,
                        R::Err(c, s) => panic!("merge failed {c}:{s}"),
                    };
                    merged = merge_delims(&pair().c, &merged).1 .0;
                    merged.truncate(mn);
                    let p2 = [
                        (ZSTD_c_compressionLevel, level),
                        (ZSTD_c_blockDelimiters, ZSTD_sf_noBlockDelimiters),
                        (ZSTD_c_validateSequences, 1),
                        (ZSTD_c_checksumFlag, checksum),
                    ];
                    let (r, f2) = diff_bytes(&format!("{base}/merged"), |l| {
                        compress_seqs(l, &p2, &merged, &src, cap)
                    });
                    if let R::Ok(cs) = r {
                        roundtrip(&format!("{base}/merged"), &f2.0[..cs], &src);
                    }
                }
            }
        }
    }
}

// ===========================================================================
// STEP 5 — invalid sequences under ZSTD_c_validateSequences == 1 (Phase C)
// ===========================================================================
//
// Everything in this section runs with `ZSTD_c_validateSequences == 1`.  The
// header is explicit that with 0 the function "blindly accepts the Sequences
// provided. Invalid Sequences cause undefined behavior", so a MUTATED array is
// never fed with validation off.
//
// Two families of value are deliberately kept OUT of the mutation pool because
// they are out of contract even with validation ON — the reference C has 32-bit
// wrap-around holes that turn them into memory corruption rather than an error:
//
//  * `offset >= 0xFFFFFFFD`.  `OFFSET_TO_OFFBASE(offset) == offset + ZSTD_REP_NUM`
//    (== offset+3) is computed in `unsigned int`, so `offset == 0xFFFFFFFD`
//    produces `offBase == 0`.  `ZSTD_validateSequence` then compares
//    `0 > offsetBound+3`, which is false, so the sequence is ACCEPTED; the
//    subsequent `ZSTD_storeSeq` has only `assert(offBase > 0)` to protect it and
//    `ZSTD_highbit32(0)` (`__builtin_clz(0)`) is undefined.  Evidence:
//    zstd_compress.c:6615 (the comparison) and zstd_compress_internal.h's
//    `ZSTD_storeSeq` assert, with DEBUGLEVEL 0 in this build.
//  * `litLength + matchLength >= 2^32` for a single sequence.
//    `blockSize_explicitDelimiter` (zstd_compress.c:6905) accumulates
//    `inSeqs[spos].litLength + inSeqs[spos].matchLength` — an `unsigned int`
//    addition — into a `size_t`, so a wrapping pair sneaks past both the
//    `> blockSize` and the `> remaining` guards at 6932/6934 and reaches
//    `ZSTD_storeSeq` with a multi-gigabyte litLength.
//
// The pool below therefore keeps offsets <= 0x7FFFFFFF and lengths <= 300000.

/// Values a mutated `offset` may take. All are <= 0x7FFFFFFF, see above.
fn offset_pool(src_size: usize, window_size: usize) -> Vec<c_uint> {
    let mut v: Vec<c_uint> = vec![0, 1, 2, 3, 0x7FFF_FFFF];
    for base in [src_size, window_size] {
        for d in [0usize, 1, 2] {
            v.push(base.saturating_add(d).min(0x7FFF_FFFF) as c_uint);
            if base > d {
                v.push((base - d) as c_uint);
            }
        }
    }
    v.push(ZSTD_BLOCKSIZE_MAX as c_uint);
    v.push(ZSTD_BLOCKSIZE_MAX as c_uint + 1);
    v
}

/// Values a mutated `litLength` / `matchLength` may take.
fn len_pool(src_size: usize) -> Vec<c_uint> {
    let mut v: Vec<c_uint> = vec![0, 1, 2, 3, 4, 5, 6, 7, 8, 16];
    v.push(ZSTD_BLOCKSIZE_MAX as c_uint - 1);
    v.push(ZSTD_BLOCKSIZE_MAX as c_uint);
    v.push(ZSTD_BLOCKSIZE_MAX as c_uint + 1);
    v.push(src_size.min(300_000) as c_uint);
    v.push((src_size + 1).min(300_000) as c_uint);
    v.push(300_000);
    v
}

/// Apply one random mutation to `seqs`, returning a label describing it.
fn mutate(
    rng: &mut Rng,
    seqs: &mut Vec<ZSTD_Sequence>,
    src_size: usize,
    window_size: usize,
    min_match: c_uint,
) -> String {
    if seqs.is_empty() {
        seqs.push(ZSTD_Sequence::default());
        return "push-delim-into-empty".to_string();
    }
    let i = rng.below(seqs.len());
    match rng.below(13) {
        // offset == 0 with matchLength != 0: a malformed block delimiter.
        0 => {
            seqs[i].offset = 0;
            seqs[i].matchLength = 1 + rng.below(8) as c_uint;
            format!("of0-ml{}@{i}", seqs[i].matchLength)
        }
        // offset beyond the window / beyond the bytes decoded so far.
        1 => {
            let p = offset_pool(src_size, window_size);
            seqs[i].offset = *rng.pick(&p);
            format!("of={}@{i}", seqs[i].offset)
        }
        // matchLength below the minMatch lower bound (3 or 4).
        2 => {
            seqs[i].matchLength = rng.below(min_match as usize + 1) as c_uint;
            format!("ml={}@{i}", seqs[i].matchLength)
        }
        // litLength + matchLength past srcSize.
        3 => {
            let p = len_pool(src_size);
            seqs[i].litLength = *rng.pick(&p);
            format!("ll={}@{i}", seqs[i].litLength)
        }
        4 => {
            let p = len_pool(src_size);
            seqs[i].matchLength = *rng.pick(&p);
            format!("mlpool={}@{i}", seqs[i].matchLength)
        }
        // totals no longer sum to srcSize (off by one, either way).
        5 => {
            seqs[i].litLength = seqs[i].litLength.wrapping_add(1);
            format!("ll+1@{i}")
        }
        6 => {
            seqs[i].litLength = seqs[i].litLength.saturating_sub(1);
            format!("ll-1@{i}")
        }
        // `rep` out of its documented [0,3] range. ZSTD_compressSequences
        // documents that it ignores `rep` entirely, so this must be inert.
        7 => {
            seqs[i].rep = *rng.pick(&[4u32, 5, 0xFFFF_FFFF, 0x8000_0000]);
            format!("rep={}@{i}", seqs[i].rep)
        }
        // a zero-length sequence in the middle of the array.
        8 => {
            seqs.insert(i, ZSTD_Sequence::default());
            format!("insert-zero@{i}")
        }
        // drop the trailing delimiter (explicit mode: "Block delimiter not found").
        9 => {
            seqs.pop();
            "pop-last".to_string()
        }
        // make one block exceed ZSTD_BLOCKSIZE_MAX.
        10 => {
            seqs[i].matchLength = ZSTD_BLOCKSIZE_MAX as c_uint + 1 + rng.below(64) as c_uint;
            format!("huge-ml={}@{i}", seqs[i].matchLength)
        }
        // truncate the array at a random point.
        11 => {
            seqs.truncate(i);
            format!("truncate@{i}")
        }
        // duplicate a sequence (breaks the totals and can break the delimiters).
        _ => {
            let s = seqs[i];
            seqs.insert(i, s);
            format!("dup@{i}")
        }
    }
}

/// Hand-built invalid arrays, one per distinct `RETURN_ERROR` site of the
/// explicit-delimiter path, so that the *specific* error code of each site is
/// pinned rather than merely "some error".
#[test]
fn t09_compress_sequences_invalid_handpicked() {
    covers(&[
        "CFG:190-196",
        "CFG:206",
        "ERR:compress/zstd_compress.c:6615", "ERR:compress/zstd_compress.c:6617",
        "ERR:compress/zstd_compress.c:6690", "ERR:compress/zstd_compress.c:6695",
        "ERR:compress/zstd_compress.c:6728", "ERR:compress/zstd_compress.c:6844",
        "ERR:compress/zstd_compress.c:6908", "ERR:compress/zstd_compress.c:6914",
        "ERR:compress/zstd_compress.c:6932", "ERR:compress/zstd_compress.c:6934",
    ]);
    let d = |ll: c_uint| ZSTD_Sequence { offset: 0, litLength: ll, matchLength: 0, rep: 0 };
    let s = |of: c_uint, ll: c_uint, ml: c_uint| ZSTD_Sequence {
        offset: of,
        litLength: ll,
        matchLength: ml,
        rep: 0,
    };
    let src = corpus(Corpus::Text, 200_000, 0x5EED_0031);

    // (label, blockDelimiters, minMatch, srcSize, sequences)
    type Case = (&'static str, c_int, c_int, usize, Vec<ZSTD_Sequence>);
    let cases: Vec<Case> = vec![
        // 6914 / 6695: no delimiter at all in explicit mode.
        ("no-delim", ZSTD_sf_explicitBlockDelimiters, 3, 12, vec![s(1, 4, 8)]),
        // 6908: offset == 0 but matchLength != 0.
        ("delim-ml5", ZSTD_sf_explicitBlockDelimiters, 3, 12, vec![s(0, 4, 5), d(3)]),
        // 6934: the block describes 12 bytes but srcSize is 10.
        ("block>src", ZSTD_sf_explicitBlockDelimiters, 3, 10, vec![s(1, 4, 8), d(0)]),
        // 6932: the block describes more than ZSTD_BLOCKSIZE_MAX.
        (
            "block>blockmax",
            ZSTD_sf_explicitBlockDelimiters,
            3,
            200_000,
            vec![s(1, 8, 140_000), d(0)],
        ),
        // 6728: the delimiter's litLength leaves srcSize unaccounted for.
        ("short-block", ZSTD_sf_explicitBlockDelimiters, 3, 100, vec![s(1, 4, 8), d(0)]),
        // 6615: offset far beyond posInSrc with no dictionary.
        ("of-too-large", ZSTD_sf_explicitBlockDelimiters, 3, 12, vec![s(100_000, 4, 8), d(0)]),
        // 6617: matchLength 3 is fine at minMatch 3 ...
        ("ml3-mm3", ZSTD_sf_explicitBlockDelimiters, 3, 7, vec![s(1, 4, 3), d(0)]),
        // ... and rejected at minMatch 4.
        ("ml3-mm4", ZSTD_sf_explicitBlockDelimiters, 4, 7, vec![s(1, 4, 3), d(0)]),
        ("ml2-mm3", ZSTD_sf_explicitBlockDelimiters, 3, 6, vec![s(1, 4, 2), d(0)]),
        // empty array with srcSize != 0 (explicit and noDelim).
        ("empty-src100-expl", ZSTD_sf_explicitBlockDelimiters, 3, 100, vec![]),
        ("empty-src100-nodelim", ZSTD_sf_noBlockDelimiters, 3, 100, vec![]),
        // nbSequences == 0 with srcSize == 0: the empty-frame special case.
        ("empty-src0-expl", ZSTD_sf_explicitBlockDelimiters, 3, 0, vec![]),
        ("empty-src0-nodelim", ZSTD_sf_noBlockDelimiters, 3, 0, vec![]),
        // srcSize == 0 with a single delimiter (CONFIGS row 197).
        ("delim-src0", ZSTD_sf_explicitBlockDelimiters, 3, 0, vec![d(0)]),
        ("delim-ll5-src0", ZSTD_sf_explicitBlockDelimiters, 3, 0, vec![d(5)]),
        // a zero-length sequence in the middle, noBlockDelimiters mode.
        (
            "zero-mid-nodelim",
            ZSTD_sf_noBlockDelimiters,
            3,
            40,
            vec![s(1, 8, 8), d(0), s(1, 8, 8), s(1, 4, 4)],
        ),
        // rep out of range must be ignored entirely (valid parse otherwise).
        (
            "rep-oob",
            ZSTD_sf_explicitBlockDelimiters,
            3,
            24,
            vec![
                ZSTD_Sequence { offset: 1, litLength: 8, matchLength: 8, rep: 0xFFFF_FFFF },
                ZSTD_Sequence { offset: 1, litLength: 0, matchLength: 4, rep: 4 },
                ZSTD_Sequence { offset: 0, litLength: 4, matchLength: 0, rep: 5 },
            ],
        ),
    ];

    for (name, delims, mm, ssize, seqs) in cases {
        let params = [
            (ZSTD_c_compressionLevel, 3),
            (ZSTD_c_minMatch, mm),
            (ZSTD_c_blockDelimiters, delims),
            (ZSTD_c_validateSequences, 1),
        ];
        let cap = compress_bound(&pair().c, ssize).max(64);
        let lbl = format!("bad/{name}/d={delims}/mm={mm}/n={ssize}");
        let (r, frame) = diff_bytes(&lbl, |l| {
            compress_seqs(l, &params, &seqs, &src[..ssize], cap)
        });
        // Whenever the C accepts the parse, both libraries must produce the same
        // frame AND both must decode it the same way.  The decoded bytes need
        // not equal `src`: `ZSTD_compressSequences` trusts the sequences, so a
        // hand-built parse that does not describe `src` legitimately
        // reconstructs something else (e.g. the "rep-oob" case, whose
        // `{offset:1, litLength:0, matchLength:4}` becomes a repcode match).
        if let R::Ok(cs) = r {
            diff_bytes(&format!("bad-dec/{lbl}"), |l| {
                decompress_simple(l, &frame.0[..cs], ssize + 16)
            });
        }
    }
}

/// Randomized mutation of a VALID sequence array, 640 cases from a fixed seed.
/// Both libraries must return the same `R` and leave the same bytes in the whole
/// destination buffer — including the cases where the mutation happens to leave
/// the parse valid, where the compressed frame must match byte for byte and
/// still decompress.
#[test]
fn t10_compress_sequences_invalid_random() {
    covers(&[
        "CFG:190-196",
        "ERR:compress/zstd_compress.c:6615", "ERR:compress/zstd_compress.c:6617",
        "ERR:compress/zstd_compress.c:6690", "ERR:compress/zstd_compress.c:6695",
        "ERR:compress/zstd_compress.c:6728", "ERR:compress/zstd_compress.c:6844",
        "ERR:compress/zstd_compress.c:6908", "ERR:compress/zstd_compress.c:6914",
        "ERR:compress/zstd_compress.c:6932", "ERR:compress/zstd_compress.c:6934",
    ]);
    let bases: &[(Corpus, usize, c_int)] = &[
        (Corpus::Text, 4096, 3),
        (Corpus::LongRepeats, 40000, 5),
        (Corpus::Periodic, 1024, 3),
        (Corpus::Mixed, 200_000, 9),
        (Corpus::Random, 8192, 1),
        (Corpus::Zeros, 70000, 19),
        (Corpus::SmallAlphabet, 12345, 3),
        (Corpus::Counter, 300, 3),
    ];
    let mut rng = Rng::new(0xC0FFEE_1234_5678);
    let mut done = 0usize;
    let mut outcomes: std::collections::BTreeMap<String, usize> =
        std::collections::BTreeMap::new();
    for &(kind, n, level) in bases {
        let src = corpus(kind, n, 0x5EED_0032);
        let gp = [(ZSTD_c_compressionLevel, level)];
        let Some(explicit) = gen_fixture(&format!("rndbase/{kind:?}/n={n}"), &gp, &src) else {
            continue;
        };
        let merged = {
            let (r, v) = merge_delims(&pair().c, &explicit);
            let mut v = v.0;
            v.truncate(match r {
                R::Ok(k) => k,
                R::Err(c, s) => panic!("merge failed {c}:{s}"),
            });
            v
        };
        // windowLog actually applied for this level/srcSize governs the offset
        // bound inside ZSTD_validateSequence; 1<<22 covers every level here.
        let window = 1usize << 22;
        for mm in [3i32, 4, 6] {
            for round in 0..27 {
                for &delims in &[ZSTD_sf_explicitBlockDelimiters, ZSTD_sf_noBlockDelimiters] {
                    let mut seqs = if delims == ZSTD_sf_explicitBlockDelimiters {
                        explicit.clone()
                    } else {
                        merged.clone()
                    };
                    // 1..=3 stacked mutations, so multi-fault arrays occur too.
                    let nmut = 1 + rng.below(3);
                    let mut tags = Vec::new();
                    for _ in 0..nmut {
                        tags.push(mutate(&mut rng, &mut seqs, n, window, mm as c_uint));
                    }
                    let params = [
                        (ZSTD_c_compressionLevel, level),
                        (ZSTD_c_minMatch, mm),
                        (ZSTD_c_blockDelimiters, delims),
                        (ZSTD_c_validateSequences, 1),
                    ];
                    let cap = compress_bound(&pair().c, n).max(64);
                    let lbl = format!(
                        "rnd/{kind:?}/n={n}/lvl={level}/mm={mm}/d={delims}/r={round}/[{}]",
                        tags.join("+")
                    );
                    let (r, frame) = diff_bytes(&lbl, |l| {
                        compress_seqs(l, &params, &seqs, &src, cap)
                    });
                    *outcomes
                        .entry(match &r {
                            R::Ok(_) => "Ok".to_string(),
                            R::Err(c, _) => format!("E{c}"),
                        })
                        .or_insert(0) += 1;
                    // A mutation that leaves a valid parse must still produce a
                    // frame both libraries decode identically.
                    if let R::Ok(cs) = r {
                        diff_bytes(&format!("rnd-dec/{lbl}"), |l| {
                            decompress_simple(l, &frame.0[..cs], n + 16)
                        });
                    }
                    done += 1;
                }
            }
        }
    }
    assert!(done >= 400, "only {done} randomized mutations ran");
    // Guard against a vacuous sweep: a substantial number of mutations must be
    // REJECTED and a substantial number must still be ACCEPTED, otherwise the
    // sweep would be testing only one of the two code paths.  (Every rejection
    // in this section is `externalSequences_invalid` (107) — that is the single
    // code every invalid-sequence site in `ZSTD_compressSequences` uses.)
    let nok = *outcomes.get("Ok").unwrap_or(&0);
    let nerr: usize = outcomes.iter().filter(|(k, _)| *k != "Ok").map(|(_, v)| *v).sum();
    assert!(
        nok >= 50 && nerr >= 50,
        "mutation sweep is lopsided: {outcomes:?} over {done} mutations"
    );
    eprintln!("t10 outcomes: {outcomes:?} over {done} mutations");
}

// ===========================================================================
// STEP 6 — ZSTD_compressSequencesAndLiterals
// ===========================================================================

/// One `ZSTD_compressSequencesAndLiterals` call on a fresh CCtx.
///
/// `litCapacity` is the *declared* capacity that the C compares against
/// `litSize` (zstd_compress.c:7598); the buffer actually handed over is always
/// physically at least `litSize + 8` bytes long, because the entropy coder reads
/// in 8-byte gulps and the header demands that slack. Varying the declared value
/// independently of the physical one is what makes the `litCapacity < litSize`
/// check observable without introducing a real out-of-bounds read.
#[allow(clippy::too_many_arguments)]
fn compress_seqs_lits(
    l: &Lib,
    params: &[(c_int, c_int)],
    seqs: &[ZSTD_Sequence],
    lits: &[u8],
    lit_size: usize,
    lit_capacity: usize,
    decompressed_size: usize,
    cap: usize,
) -> (R, Blob) {
    let ctx = Ctx::cctx(l);
    if let Some(e) = set_params(l, &ctx, params) {
        return (e, Blob(Vec::new()));
    }
    let mut dst = vec![0xCDu8; cap];
    let f = l.sym::<FnCompressSequencesAndLiterals>("ZSTD_compressSequencesAndLiterals");
    let n = unsafe {
        f(
            ctx.ptr,
            dst.as_mut_ptr() as *mut c_void,
            cap,
            seqs.as_ptr(),
            seqs.len(),
            lits.as_ptr() as *const c_void,
            lit_size,
            lit_capacity,
            decompressed_size,
        )
    };
    (res(l, n), Blob(dst))
}

/// Pull the literals out of `src` according to `seqs`, i.e. rebuild exactly the
/// buffer `ZSTD_compressSequencesAndLiterals` expects. The returned vector is
/// padded with 8 extra bytes (the documented `litSize + 8` slack).
fn extract_literals(seqs: &[ZSTD_Sequence], src: &[u8]) -> (Vec<u8>, usize) {
    let mut lits = Vec::new();
    let mut pos = 0usize;
    for s in seqs {
        let ll = s.litLength as usize;
        let end = (pos + ll).min(src.len());
        lits.extend_from_slice(&src[pos.min(src.len())..end]);
        pos = end + s.matchLength as usize;
    }
    let n = lits.len();
    lits.extend_from_slice(&[0u8; 8]);
    (lits, n)
}

fn seq_total(seqs: &[ZSTD_Sequence]) -> usize {
    seqs.iter()
        .map(|s| s.litLength as usize + s.matchLength as usize)
        .sum()
}

/// The happy path of `ZSTD_compressSequencesAndLiterals` (CONFIGS row 201):
/// explicit delimiters, `checksumFlag == 0`, `validateSequences == 0`,
/// `litBufCapacity == litSize + 8`, `decompressedSize` == the exact sum of all
/// sequence lengths. Runs `ZSTD_get1BlockSummary` ->
/// `ZSTD_convertBlockSequences` -> `ZSTD_entropyCompressSeqStore_internal` over
/// the caller's literal buffer, once per block.
///
/// Incompressible blocks are expected to come back as
/// `cannotProduce_uncompressedBlock` (49) — the variant has no source to fall
/// back on (zstd_compress.c:7550).
#[test]
fn t11_compress_sequences_and_literals_valid() {
    covers(&["CFG:201", "CFG:207", "ERR:compress/zstd_compress.c:7550"]);
    for &kind in ALL_CORPORA {
        for &n in &[100usize, 1024, 65536, 131072, 300_000] {
            for &level in &[1i32, 12, 19] {
                for &repres in &[ZSTD_ps_auto, ZSTD_ps_enable, ZSTD_ps_disable] {
                    let src = corpus(kind, n, 0x5EED_0041);
                    let gp = [(ZSTD_c_compressionLevel, level)];
                    let lbl = format!("csl/{kind:?}/n={n}/lvl={level}/r={repres}");
                    let Some(seqs) = gen_fixture(&lbl, &gp, &src) else { continue };
                    let (lits, lit_size) = extract_literals(&seqs, &src);
                    let total = seq_total(&seqs);
                    let params = [
                        (ZSTD_c_compressionLevel, level),
                        (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                        (ZSTD_c_repcodeResolution, repres),
                    ];
                    let cap = compress_bound(&pair().c, n).max(64);
                    let (r, frame) = diff_bytes(&lbl, |l| {
                        compress_seqs_lits(
                            l, &params, &seqs, &lits, lit_size, lit_size + 8, total, cap,
                        )
                    });
                    if let R::Ok(cs) = r {
                        // The parse came from ZSTD_generateSequences on `src`, so
                        // the frame must decode back to exactly `src`.
                        roundtrip(&lbl, &frame.0[..cs], &src[..total]);
                    }
                }
            }
        }
    }
}

/// The three unconditional parameter rejections of
/// `ZSTD_compressSequencesAndLiterals`, in the order the C checks them
/// (zstd_compress.c:7603 delimiters -> :7606 validation -> :7609 checksum), plus
/// the `litCapacity` check at :7598 which runs BEFORE
/// `ZSTD_CCtx_init_compressStream2` and therefore before all three.
#[test]
fn t12_compress_sequences_and_literals_rejections() {
    covers(&[
        "CFG:202-206",
        "CFG:208-209",
        "ERR:compress/zstd_compress.c:7598", "ERR:compress/zstd_compress.c:7603",
        "ERR:compress/zstd_compress.c:7606", "ERR:compress/zstd_compress.c:7609",
        "ERR:compress/zstd_compress.c:7490", "ERR:compress/zstd_compress.c:7495",
        "ERR:compress/zstd_compress.c:7508", "ERR:compress/zstd_compress.c:7578",
        "ERR:compress/zstd_compress.c:7579", "ERR:compress/zstd_compress.c:7464",
    ]);
    let src = corpus(Corpus::Text, 65536, 0x5EED_0042);
    let seqs = gen_fixture("cslrej", &[(ZSTD_c_compressionLevel, 3)], &src).unwrap();
    let (lits, lit_size) = extract_literals(&seqs, &src);
    let total = seq_total(&seqs);
    let cap = compress_bound(&pair().c, src.len());

    // Every combination of the three rejected parameters, so the *order* of the
    // three `RETURN_ERROR`s is pinned rather than just each one alone.
    for &delims in &[ZSTD_sf_noBlockDelimiters, ZSTD_sf_explicitBlockDelimiters] {
        for &validate in &[0i32, 1] {
            for &checksum in &[0i32, 1] {
                let params = [
                    (ZSTD_c_compressionLevel, 3),
                    (ZSTD_c_blockDelimiters, delims),
                    (ZSTD_c_validateSequences, validate),
                    (ZSTD_c_checksumFlag, checksum),
                ];
                let lbl = format!("cslrej/d={delims}/v={validate}/ck={checksum}");
                diff_bytes(&lbl, |l| {
                    compress_seqs_lits(
                        l, &params, &seqs, &lits, lit_size, lit_size + 8, total, cap,
                    )
                });
            }
        }
    }

    // `litCapacity` sweep. CONFIGS row 205: the C checks `litCapacity < litSize`
    // even though the docs demand `litSize + 8`, so litSize and litSize+7 must be
    // ACCEPTED. Pin whatever the C actually does.
    let base = [
        (ZSTD_c_compressionLevel, 3),
        (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
    ];
    for lc in [
        0usize,
        1,
        lit_size.saturating_sub(2),
        lit_size.saturating_sub(1),
        lit_size,
        lit_size + 1,
        lit_size + 7,
        lit_size + 8,
        lit_size + 64,
    ] {
        let lbl = format!("cslcap/litCapacity={lc}/litSize={lit_size}");
        diff_bytes(&lbl, |l| {
            compress_seqs_lits(l, &base, &seqs, &lits, lit_size, lc, total, cap)
        });
    }

    // `litSize` mismatching the sum of the sequences' litLength fields, and a
    // wrong `decompressedSize` in both directions.
    for dl in [-64i64, -8, -1, 0, 1, 8, 64] {
        let ls = (lit_size as i64 + dl).max(0) as usize;
        let lbl = format!("csllit/litSize={ls}(base {lit_size})");
        diff_bytes(&lbl, |l| {
            compress_seqs_lits(l, &base, &seqs, &lits, ls, ls + 8, total, cap)
        });
    }
    for dd in [-131_073i64, -65_536, -1, 0, 1, 65_536] {
        let ds = (total as i64 + dd).max(0) as usize;
        let lbl = format!("csldec/decompressedSize={ds}(base {total})");
        diff_bytes(&lbl, |l| {
            compress_seqs_lits(l, &base, &seqs, &lits, lit_size, lit_size + 8, ds, cap)
        });
    }

    // nbSequences == 0 (zstd_compress.c:7490) and the single-delimiter empty
    // frame (zstd_compress.c:7495).
    let empty: Vec<ZSTD_Sequence> = Vec::new();
    let one = vec![ZSTD_Sequence::default()];
    let lits0 = vec![0u8; 16];
    for (name, s, ls, ds) in [
        ("nbSeq0-lit0", &empty, 0usize, 0usize),
        ("nbSeq0-lit8", &empty, 8, 8),
        ("delim-only", &one, 0, 0),
    ] {
        let lbl = format!("cslempty/{name}");
        diff_bytes(&lbl, |l| {
            compress_seqs_lits(l, &base, s, &lits0, ls, ls + 8, ds, cap)
        });
    }

    // A sequence array with NO terminating matchLength == 0 delimiter
    // (`ZSTD_get1BlockSummary` walks off the end, zstd_compress.c:7464).
    let no_delim = vec![ZSTD_Sequence { offset: 1, litLength: 4, matchLength: 8, rep: 0 }];
    diff_bytes("cslnodelim", |l| {
        compress_seqs_lits(l, &base, &no_delim, &lits0, 4, 12, 12, cap)
    });

    // Block-level literal shortfall (zstd_compress.c:7508): the block's
    // sequences claim 8 literals but only 4 are supplied.
    let short_lits = vec![
        ZSTD_Sequence { offset: 1, litLength: 8, matchLength: 4, rep: 0 },
        ZSTD_Sequence::default(),
    ];
    diff_bytes("csllitshort", |l| {
        compress_seqs_lits(l, &base, &short_lits, &lits0, 4, 12, 12, cap)
    });
}

// ===========================================================================
// STEP 7 — dstCapacity sweeps
// ===========================================================================
//
// `ZSTD_compressSequences` (zstd_compress.c:7078) and
// `ZSTD_compressSequencesAndLiterals` (zstd_compress.c:7615) both call
// `ZSTD_writeFrameHeader` and then do
//
//     op += frameHeaderSize; dstCapacity -= frameHeaderSize; cSize += frameHeaderSize;
//
// with NO `FORWARD_IF_ERROR`.  `ZSTD_writeFrameHeader` fails whenever
// `dstCapacity < ZSTD_FRAMEHEADERSIZE_MAX` (18) — zstd_compress.c:4712 — and
// returns `(size_t)-70`, so for every `dstCapacity` in 0..18 the reference C
// walks `op` 70 bytes BACKWARDS and writes the first block header / compressed
// block there, i.e. *before* the destination buffer.  It then returns either a
// clean `dstSize_tooSmall` (when the block loop itself runs out of room) or the
// nonsense code 67 ("Unspecified error code" == 70 minus the 3 header bytes it
// managed to emit) for the `srcSize == 0` path.
//
// That underflow is out of contract, but it is *deterministic*, so rather than
// dropping the whole 0..18 range this section places `dst` 512 bytes into a
// larger allocation this test owns and compares the ENTIRE allocation.  No
// memory outside the test's own buffer is ever touched, and the two libraries
// are held to producing bit-identical results including the 70 bytes written
// below `dst`.  (Verified empirically: both write the same bytes there.)

/// Slack placed before and after `dst`; comfortably more than the 70-byte
/// underflow the unchecked `ZSTD_writeFrameHeader` error can produce.
const PAD: usize = 512;

/// `ZSTD_compressSequences` with `dst` at `buf + PAD`; the returned `Blob` is the
/// whole padded allocation.
fn compress_seqs_padded(
    l: &Lib,
    params: &[(c_int, c_int)],
    seqs: &[ZSTD_Sequence],
    src: &[u8],
    dcap: usize,
) -> (R, Blob) {
    let ctx = Ctx::cctx(l);
    if let Some(e) = set_params(l, &ctx, params) {
        return (e, Blob(Vec::new()));
    }
    let mut buf = vec![0xA7u8; PAD + dcap + PAD];
    let dstp = unsafe { buf.as_mut_ptr().add(PAD) };
    let f = l.sym::<FnCompressSequences>("ZSTD_compressSequences");
    let n = unsafe {
        f(
            ctx.ptr,
            dstp as *mut c_void,
            dcap,
            seqs.as_ptr(),
            seqs.len(),
            src.as_ptr() as *const c_void,
            src.len(),
        )
    };
    (res(l, n), Blob(buf))
}

/// `ZSTD_compressSequencesAndLiterals` with the same padding discipline.
#[allow(clippy::too_many_arguments)]
fn compress_seqs_lits_padded(
    l: &Lib,
    params: &[(c_int, c_int)],
    seqs: &[ZSTD_Sequence],
    lits: &[u8],
    lit_size: usize,
    decompressed_size: usize,
    dcap: usize,
) -> (R, Blob) {
    let ctx = Ctx::cctx(l);
    if let Some(e) = set_params(l, &ctx, params) {
        return (e, Blob(Vec::new()));
    }
    let mut buf = vec![0xA7u8; PAD + dcap + PAD];
    let dstp = unsafe { buf.as_mut_ptr().add(PAD) };
    let f = l.sym::<FnCompressSequencesAndLiterals>("ZSTD_compressSequencesAndLiterals");
    let n = unsafe {
        f(
            ctx.ptr,
            dstp as *mut c_void,
            dcap,
            seqs.as_ptr(),
            seqs.len(),
            lits.as_ptr() as *const c_void,
            lit_size,
            lit_size + 8,
            decompressed_size,
        )
    };
    (res(l, n), Blob(buf))
}

/// `dstCapacity` sweep for `ZSTD_compressSequences`: 0..=20 (which straddles
/// `ZSTD_FRAMEHEADERSIZE_MAX` == 18 and the `dstCapacity < 4` empty-frame guard
/// at zstd_compress.c:6962), then the exact required size, one byte short
/// (`dstSize_tooSmall`, 70), a set of intermediate capacities that make a
/// *later* block run out of room (zstd_compress.c:7001 and the
/// `ZSTD_noCompressBlock` / `ZSTD_rleCompressBlock` failures), and a generously
/// oversized buffer.  With `ZSTD_c_checksumFlag` the last four bytes are the
/// trailer written at zstd_compress.c:7102.
#[test]
fn t13_compress_sequences_dstcapacity() {
    covers(&[
        "CFG:197",
        "CFG:199-200",
        "ERR:compress/zstd_compress.c:4712", "ERR:compress/zstd_compress.c:6962",
        "ERR:compress/zstd_compress.c:7001", "ERR:compress/zstd_compress.c:7102",
        "ERR:compress/zstd_compress.c:2934", "ERR:compress/zstd_compress.c:2940",
        "ERR:compress/zstd_compress.c:2967", "ERR:compress/zstd_compress.c:2981",
        "ERR:compress/zstd_compress.c:3026", "ERR:compress/zstd_compress.c:3030",
    ]);
    for &(kind, n) in &[
        (Corpus::Text, 0usize),
        (Corpus::Text, 1024),
        (Corpus::LongRepeats, 65536),
        (Corpus::Periodic, 200_000),
        (Corpus::Random, 8192),
    ] {
        let src = corpus(kind, n, 0x5EED_0051);
        let seqs = if n == 0 {
            // srcSize == 0 with a single delimiter is the empty-frame recipe of
            // CONFIGS row 197.
            vec![ZSTD_Sequence::default()]
        } else {
            match gen_fixture(&format!("dcap/{kind:?}/n={n}"), &[(ZSTD_c_compressionLevel, 3)], &src) {
                Some(v) => v,
                None => continue,
            }
        };
        for &checksum in &[0i32, 1] {
            let params = [
                (ZSTD_c_compressionLevel, 3),
                (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                (ZSTD_c_validateSequences, 1),
                (ZSTD_c_checksumFlag, checksum),
            ];
            // The exact required size, measured with a generous buffer.
            let bound = compress_bound(&pair().c, n).max(64);
            let exact = match compress_seqs_padded(&pair().c, &params, &seqs, &src, bound).0 {
                R::Ok(v) => v,
                R::Err(c, s) => panic!("dcap probe failed {c}:{s}"),
            };
            let mut caps: Vec<usize> = (0..=20).collect();
            for d in [4usize, 3, 2, 1, 0] {
                caps.push(exact.saturating_sub(d));
            }
            caps.push(exact + 1);
            caps.push(bound);
            // Capacities that starve a *later* block rather than the header.
            for frac in [2usize, 3, 4, 8] {
                caps.push(24 + exact / frac);
            }
            caps.sort_unstable();
            caps.dedup();
            for dcap in caps {
                diff_bytes(
                    &format!("dcap/{kind:?}/n={n}/ck={checksum}/cap={dcap}(exact={exact})"),
                    |l| compress_seqs_padded(l, &params, &seqs, &src, dcap),
                );
            }
        }
    }
}

/// The same sweep for `ZSTD_compressSequencesAndLiterals`. Here the empty-frame
/// guard is `dstCapacity < 3` (zstd_compress.c:7495, one less than
/// `ZSTD_compressSequences`) and the per-block guard is at
/// zstd_compress.c:7524.
#[test]
fn t14_compress_sequences_and_literals_dstcapacity() {
    covers(&[
        "CFG:205-206",
        "ERR:compress/zstd_compress.c:7495", "ERR:compress/zstd_compress.c:7524",
        "ERR:compress/zstd_compress.c:4712",
    ]);
    for &(kind, n) in &[
        (Corpus::Text, 1024usize),
        (Corpus::LongRepeats, 65536),
        (Corpus::Periodic, 200_000),
    ] {
        let src = corpus(kind, n, 0x5EED_0052);
        let lbl0 = format!("cslcap/{kind:?}/n={n}");
        let Some(seqs) = gen_fixture(&lbl0, &[(ZSTD_c_compressionLevel, 3)], &src) else {
            continue;
        };
        let (lits, lit_size) = extract_literals(&seqs, &src);
        let total = seq_total(&seqs);
        let params = [
            (ZSTD_c_compressionLevel, 3),
            (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
        ];
        let bound = compress_bound(&pair().c, n).max(64);
        let exact =
            match compress_seqs_lits_padded(&pair().c, &params, &seqs, &lits, lit_size, total, bound)
                .0
            {
                R::Ok(v) => v,
                R::Err(..) => 0,
            };
        let mut caps: Vec<usize> = (0..=20).collect();
        if exact > 0 {
            for d in [4usize, 3, 2, 1, 0] {
                caps.push(exact.saturating_sub(d));
            }
            caps.push(exact + 1);
            for frac in [2usize, 4, 8] {
                caps.push(24 + exact / frac);
            }
        }
        caps.push(bound);
        caps.sort_unstable();
        caps.dedup();
        for dcap in caps {
            diff_bytes(&format!("{lbl0}/cap={dcap}(exact={exact})"), |l| {
                compress_seqs_lits_padded(l, &params, &seqs, &lits, lit_size, total, dcap)
            });
        }
    }

    // The single-delimiter empty frame, whose guard is `dstCapacity < 3`.
    let one = vec![ZSTD_Sequence::default()];
    let lits0 = vec![0u8; 16];
    let params = [
        (ZSTD_c_compressionLevel, 3),
        (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
    ];
    for dcap in 0..=24usize {
        diff_bytes(&format!("cslempty/cap={dcap}"), |l| {
            compress_seqs_lits_padded(l, &params, &one, &lits0, 0, 0, dcap)
        });
    }
}

/// `seqStore.maxNbSeq` exhaustion — CONFIGS row 196.
///
/// `ZSTD_resetCCtx_internal` sizes the seqStore as
/// `blockSizeMax / (minMatch == 3 || extSeqProd ? 3 : 4)`, and three separate
/// sites reject a block that reaches it:
/// `ZSTD_transferSequences_wBlockDelim` (zstd_compress.c:6690),
/// `ZSTD_transferSequences_noDelim` (zstd_compress.c:6844) and
/// `ZSTD_convertBlockSequences` (zstd_compress.c:7327), all with
/// `externalSequences_invalid` (107) and the message "Not enough memory
/// allocated. Try adjusting ZSTD_c_minMatch.".
///
/// The recipe needs `ZSTD_c_validateSequences == 0`, because with a small
/// `ZSTD_c_maxBlockSize` the only way to pack more than `blockSizeMax/4`
/// sequences into one block is `matchLength == 3` while `minMatch > 3`, which
/// `ZSTD_validateSequence` (zstd_compress.c:6617) rejects first.  This is
/// nonetheless memory-safe: `ZSTD_storeSeq` stores `mlBase = matchLength -
/// MINMATCH` against the *format* constant `MINMATCH == 3`, not against
/// `cParams.minMatch`, so `matchLength == 3` yields `mlBase == 0`; `minMatch`
/// only ever sizes `maxNbSeq`.
#[test]
fn t15_max_nb_seq_exhaustion() {
    let _sp_guard = sp_lock();
    covers(&[
        "CFG:196",
        "ERR:compress/zstd_compress.c:6690", "ERR:compress/zstd_compress.c:6844",
        "ERR:compress/zstd_compress.c:7327",
    ]);
    let src = corpus(Corpus::Periodic, 4096, 0x5EED_0053);
    for &max_block in &[1024i32, 2048] {
        for mm in ZSTD_MINMATCH_MIN..=ZSTD_MINMATCH_MAX {
            for &nseq in &[200usize, 255, 256, 257, 300, 340, 341, 342, 400] {
                // nseq sequences of {offset:1, litLength:0, matchLength:3} plus a
                // trailing delimiter carrying the rest of the block.
                let mut seqs: Vec<ZSTD_Sequence> = (0..nseq)
                    .map(|_| ZSTD_Sequence { offset: 1, litLength: 0, matchLength: 3, rep: 0 })
                    .collect();
                let used = nseq * 3;
                if used > max_block as usize {
                    continue;
                }
                seqs.push(ZSTD_Sequence {
                    offset: 0,
                    litLength: (max_block as usize - used) as c_uint,
                    matchLength: 0,
                    rep: 0,
                });
                let ssize = max_block as usize;
                for &delims in &[ZSTD_sf_explicitBlockDelimiters, ZSTD_sf_noBlockDelimiters] {
                    let mut arr = seqs.clone();
                    if delims == ZSTD_sf_noBlockDelimiters {
                        arr.pop();
                    }
                    let params = [
                        (ZSTD_c_compressionLevel, 3),
                        (ZSTD_c_minMatch, mm),
                        (ZSTD_c_maxBlockSize, max_block),
                        (ZSTD_c_windowLog, 17),
                        (ZSTD_c_blockDelimiters, delims),
                        (ZSTD_c_validateSequences, 0),
                    ];
                    let cap = compress_bound(&pair().c, ssize).max(64);
                    let lbl =
                        format!("maxnbseq/mb={max_block}/mm={mm}/n={nseq}/d={delims}");
                    diff_bytes(&lbl, |l| {
                        compress_seqs(l, &params, &arr, &src[..ssize], cap)
                    });
                }

                // ... and the same through ZSTD_compressSequencesAndLiterals,
                // which routes into ZSTD_convertBlockSequences:7327.
                let lits = vec![0x41u8; max_block as usize + 8];
                let ls = (max_block as usize - used).min(lits.len() - 8);
                let params = [
                    (ZSTD_c_compressionLevel, 3),
                    (ZSTD_c_minMatch, mm),
                    (ZSTD_c_maxBlockSize, max_block),
                    (ZSTD_c_windowLog, 17),
                    (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                ];
                let cap = compress_bound(&pair().c, ssize).max(64);
                diff_bytes(
                    &format!("maxnbseqL/mb={max_block}/mm={mm}/n={nseq}"),
                    |l| {
                        compress_seqs_lits(
                            l, &params, &seqs, &lits, ls, ls + 8, ssize, cap,
                        )
                    },
                );
            }
        }
    }
}

// ===========================================================================
// STEP 8 — the Block-Level Sequence Producer API
// ===========================================================================
//
// One single `extern "C"` producer serves BOTH libraries.  Its behaviour is a
// pure function of (mode, srcSize, outSeqsCapacity, windowSize) — the mode is
// smuggled in through the `sequenceProducerState` pointer value itself — so it
// cannot leak per-library state into the comparison, as the brief requires.
//
// Every call is additionally logged, and the log is part of the compared value:
// that pins the number of producer invocations and every argument zstd passes
// (`outSeqsCapacity`, `srcSize`, the always-NULL `dict`/`dictSize`,
// `compressionLevel` and `windowSize`), not merely the resulting frame.

/// One recorded invocation of the external sequence producer.
#[derive(Clone, Debug, PartialEq, Eq)]
struct SpCall {
    out_cap: usize,
    src_size: usize,
    dict_null: bool,
    dict_size: usize,
    level: c_int,
    window: usize,
}

static SP_LOG: std::sync::Mutex<Vec<SpCall>> = std::sync::Mutex::new(Vec::new());

/// `SP_LOG` is process-wide, because an `extern "C"` callback has nowhere else to
/// record what it saw. Every test that compares the callback LOG (as opposed to
/// just the compressed bytes) must therefore hold this lock for its whole body —
/// otherwise two such tests running on different `--test-threads` interleave
/// their `sp_reset()`/`sp_take()` pairs and steal each other's entries. That is
/// a property of the test's own bookkeeping, not of either library: when this
/// first bit, all three failing cases had byte-identical compressed output and
/// differed only in the recorded call count.
static SP_SERIAL: std::sync::Mutex<()> = std::sync::Mutex::new(());

/// Acquire the serialisation lock, ignoring poisoning (a panicking test has
/// already failed the run; the next one should still produce a real diagnosis).
fn sp_lock() -> std::sync::MutexGuard<'static, ()> {
    match SP_SERIAL.lock() {
        Ok(g) => g,
        Err(e) => e.into_inner(),
    }
}

fn sp_reset() {
    if let Ok(mut g) = SP_LOG.lock() {
        g.clear();
    }
}
fn sp_take() -> Vec<SpCall> {
    match SP_LOG.lock() {
        Ok(mut g) => std::mem::take(&mut *g),
        Err(_) => Vec::new(),
    }
}

// The producer modes. The value is passed as the `sequenceProducerState`
// pointer, which the producer only ever reinterprets as an integer.
/// A single literals-only sequence == the whole block (CONFIGS row 141).
const SP_LITERALS_ONLY: usize = 0;
/// One real match followed by a last-literals delimiter.
const SP_ONE_MATCH: usize = 1;
/// Up to 64 short matches followed by a last-literals delimiter.
const SP_MANY_MATCHES: usize = 2;
/// Returns `ZSTD_SEQUENCE_PRODUCER_ERROR` (zstd_compress.c:3177).
const SP_ERROR_SENTINEL: usize = 3;
/// Returns 0 for a non-empty block (zstd_compress.c:3184).
const SP_ZERO: usize = 4;
/// Returns `outSeqsCapacity + 1`, i.e. an error code that is not the sentinel.
const SP_OVERFLOW_CAP: usize = 5;
/// Fills all `outSeqsCapacity` entries with the last one being a real match, so
/// there is no room to append a delimiter (zstd_compress.c:3205).
const SP_FILL_CAP: usize = 6;
/// A parse covering more bytes than the block (zstd_compress.c:3380).
const SP_TOO_LONG: usize = 7;
/// A structurally invalid parse: `matchLength == 2` and an offset past the
/// window (CONFIGS row 141 / zstd_compress.c:6615 + :6617).
const SP_INVALID: usize = 8;
/// A valid parse whose last sequence is a real match, so
/// `ZSTD_postProcessSequenceProducerResult` has to APPEND the block delimiter.
const SP_NO_TRAILING_DELIM: usize = 9;

#[allow(clippy::too_many_arguments)]
unsafe extern "C" fn seq_prod(
    state: *mut c_void,
    out: *mut ZSTD_Sequence,
    out_cap: SizeT,
    _src: *const c_void,
    src_size: SizeT,
    dict: *const c_void,
    dict_size: SizeT,
    level: c_int,
    window: SizeT,
) -> SizeT {
    if let Ok(mut g) = SP_LOG.lock() {
        g.push(SpCall {
            out_cap,
            src_size,
            dict_null: dict.is_null(),
            dict_size,
            level,
            window,
        });
    }
    let put = |i: usize, s: ZSTD_Sequence| {
        if i < out_cap {
            unsafe { *out.add(i) = s };
        }
    };
    let delim = |ll: usize| ZSTD_Sequence {
        offset: 0,
        litLength: ll as c_uint,
        matchLength: 0,
        rep: 0,
    };
    match state as usize {
        SP_LITERALS_ONLY => {
            put(0, delim(src_size));
            1
        }
        SP_ONE_MATCH => {
            if src_size < 16 {
                put(0, delim(src_size));
                return 1;
            }
            put(
                0,
                ZSTD_Sequence { offset: 1, litLength: 4, matchLength: 4, rep: 0 },
            );
            put(1, delim(src_size - 8));
            2
        }
        SP_MANY_MATCHES => {
            if src_size < 64 || out_cap < 4 {
                put(0, delim(src_size));
                return 1;
            }
            let n = (src_size / 8).min(out_cap - 2).min(64);
            for i in 0..n {
                put(
                    i,
                    ZSTD_Sequence {
                        offset: 1 + (i % 3) as c_uint,
                        litLength: 3,
                        matchLength: 5,
                        rep: 0,
                    },
                );
            }
            put(n, delim(src_size - 8 * n));
            n + 1
        }
        SP_ERROR_SENTINEL => ZSTD_SEQUENCE_PRODUCER_ERROR,
        SP_ZERO => 0,
        SP_OVERFLOW_CAP => out_cap + 1,
        SP_FILL_CAP => {
            for i in 0..out_cap {
                put(
                    i,
                    ZSTD_Sequence { offset: 1, litLength: 0, matchLength: 3, rep: 0 },
                );
            }
            out_cap
        }
        SP_TOO_LONG => {
            put(
                0,
                ZSTD_Sequence {
                    offset: 1,
                    litLength: src_size as c_uint,
                    matchLength: 8,
                    rep: 0,
                },
            );
            put(1, delim(0));
            2
        }
        SP_INVALID => {
            if src_size < 8 {
                put(0, delim(src_size));
                return 1;
            }
            put(
                0,
                ZSTD_Sequence {
                    offset: (window + 1000) as c_uint,
                    litLength: 4,
                    matchLength: 2,
                    rep: 0,
                },
            );
            put(1, delim(src_size - 6));
            2
        }
        SP_NO_TRAILING_DELIM => {
            if src_size < 16 {
                put(0, delim(src_size));
                return 1;
            }
            put(
                0,
                ZSTD_Sequence {
                    offset: 1,
                    litLength: 4,
                    matchLength: (src_size - 4) as c_uint,
                    rep: 0,
                },
            );
            1
        }
        _ => ZSTD_SEQUENCE_PRODUCER_ERROR,
    }
}

type FnCreateCCtxParams = unsafe extern "C" fn() -> *mut c_void;
type FnFreeCCtxParams = unsafe extern "C" fn(*mut c_void) -> SizeT;
type FnCCtxParamsSetParameter = unsafe extern "C" fn(*mut c_void, c_int, c_int) -> SizeT;
type FnSetParamsUsingCCtxParams = unsafe extern "C" fn(*mut c_void, *const c_void) -> SizeT;
type FnEstimateCCtxSizeUsingCCtxParams = unsafe extern "C" fn(*const c_void) -> SizeT;

/// Result of one producer-driven compression: the producer call log, the
/// `ZSTD_compress2` status, and the exact output bytes.
type SpOut = (Vec<SpCall>, R, Blob);

/// Drive a compression through an external sequence producer.
///
/// `mode == None` registers a NULL producer, which the header documents as the
/// way to CLEAR the registration; the compression must then behave like an
/// ordinary `ZSTD_compress2`.
///
/// `via_params` routes the registration through
/// `ZSTD_CCtxParams_registerSequenceProducer` +
/// `ZSTD_CCtx_setParametersUsingCCtxParams` instead of
/// `ZSTD_registerSequenceProducer`.
fn drive_producer(
    l: &Lib,
    mode: Option<usize>,
    params: &[(c_int, c_int)],
    src: &[u8],
    via_params: bool,
) -> SpOut {
    sp_reset();
    let ctx = Ctx::cctx(l);
    let reg_cctx = l.sym::<FnRegisterSequenceProducer>("ZSTD_registerSequenceProducer");
    let reg_params =
        l.sym::<FnRegisterSequenceProducer>("ZSTD_CCtxParams_registerSequenceProducer");
    let f: Option<SeqProdF> = mode.map(|_| seq_prod as SeqProdF);
    let st = mode.unwrap_or(0) as *mut c_void;

    if via_params {
        let create = l.sym::<FnCreateCCtxParams>("ZSTD_createCCtxParams");
        let free = l.sym::<FnFreeCCtxParams>("ZSTD_freeCCtxParams");
        let setp = l.sym::<FnCCtxParamsSetParameter>("ZSTD_CCtxParams_setParameter");
        let apply = l.sym::<FnSetParamsUsingCCtxParams>("ZSTD_CCtx_setParametersUsingCCtxParams");
        let cp = unsafe { create() };
        assert!(!cp.is_null(), "[{}] ZSTD_createCCtxParams returned NULL", l.tag);
        let mut sets = Vec::new();
        for (p, v) in params {
            sets.push(res(l, unsafe { setp(cp, *p, *v) }));
        }
        unsafe { reg_params(cp, st, f) };
        let ar = res(l, unsafe { apply(ctx.ptr, cp) });
        unsafe { free(cp) };
        if sets.iter().any(|r| matches!(r, R::Err(..))) || matches!(ar, R::Err(..)) {
            return (sp_take(), ar, Blob(Vec::new()));
        }
    } else {
        if let Some(e) = set_params(l, &ctx, params) {
            return (sp_take(), e, Blob(Vec::new()));
        }
        unsafe { reg_cctx(ctx.ptr, st, f) };
    }

    let cap = compress_bound(l, src.len()).max(64);
    let mut dst = vec![0xCDu8; cap];
    let c2 = l.sym::<FnCompress2>("ZSTD_compress2");
    let n = unsafe {
        c2(
            ctx.ptr,
            dst.as_mut_ptr() as *mut c_void,
            cap,
            src.as_ptr() as *const c_void,
            src.len(),
        )
    };
    let r = res(l, n);
    if let R::Ok(k) = r {
        dst.truncate(k);
    }
    (sp_take(), r, Blob(dst))
}

/// Well-behaved producers: `ZSTD_buildSeqStore` takes the
/// `ZSTD_hasExtSeqProd` branch, `ZSTD_postProcessSequenceProducerResult` accepts
/// the parse (appending a delimiter for `SP_NO_TRAILING_DELIM`), and
/// `ZSTD_transferSequences_wBlockDelim` copies it into the seqStore.
///
/// `ZSTD_c_enableLongDistanceMatching` is pinned to `ZSTD_ps_disable` exactly as
/// the header's LIMITATIONS section instructs, because LDM plus a producer is a
/// hard `parameter_combination_unsupported`.
#[test]
fn t16_sequence_producer_valid() {
    let _sp_guard = sp_lock();
    covers(&[
        "CFG:140-143",
        "ERR:compress/zstd_compress.c:3205",
    ]);
    for &mode in &[SP_LITERALS_ONLY, SP_ONE_MATCH, SP_MANY_MATCHES, SP_NO_TRAILING_DELIM] {
        for &n in &[1024usize, 65536, 131072, 300_000] {
            for &level in &[1i32, 3, 12, 19] {
                for &validate in &[0i32, 1] {
                    for &fallback in &[0i32, 1] {
                        let src = corpus(Corpus::Text, n, 0x5EED_0061);
                        let params = [
                            (ZSTD_c_compressionLevel, level),
                            (ZSTD_c_windowLog, 20),
                            (ZSTD_c_enableLongDistanceMatching, ZSTD_ps_disable),
                            (ZSTD_c_validateSequences, validate),
                            (ZSTD_c_enableSeqProducerFallback, fallback),
                        ];
                        let lbl = format!(
                            "sp/mode={mode}/n={n}/lvl={level}/v={validate}/fb={fallback}"
                        );
                        let (log, r, frame) = diff_bytes(&lbl, |l| {
                            drive_producer(l, Some(mode), &params, &src, false)
                        });
                        assert!(!log.is_empty(), "{lbl}: producer was never called");
                        // Whatever the parse claims, both libraries must decode
                        // the resulting frame identically.
                        if let R::Ok(_) = r {
                            diff_bytes(&format!("sp-dec/{lbl}"), |l| {
                                decompress_simple(l, &frame.0, n + 16)
                            });
                        }
                    }
                }
            }
        }
    }
}

/// Failing producers.
///
/// `ZSTD_postProcessSequenceProducerResult` has three rejections — the error
/// code / over-capacity return (zstd_compress.c:3177), zero sequences for a
/// non-empty block (:3184) and a full buffer whose last entry is not a delimiter
/// (:3205) — and `ZSTD_buildSeqStore` then either propagates them
/// (`enableMatchFinderFallback == 0`, :3397) or swallows them and re-runs the
/// internal match finder (:3400ff).
///
/// The two later rejections behave differently: the over-long parse (:3380) and
/// the invalid parse forwarded out of `ZSTD_transferSequences_wBlockDelim`
/// (:3381) sit INSIDE the `!ZSTD_isError(nbPostProcessedSeqs)` branch, so
/// `ZSTD_c_enableSeqProducerFallback` cannot rescue them.
#[test]
fn t17_sequence_producer_errors() {
    let _sp_guard = sp_lock();
    covers(&[
        "CFG:140-141",
        "ERR:compress/zstd_compress.c:3177", "ERR:compress/zstd_compress.c:3184",
        "ERR:compress/zstd_compress.c:3205", "ERR:compress/zstd_compress.c:3380",
        "ERR:compress/zstd_compress.c:3381", "ERR:compress/zstd_compress.c:3397",
    ]);
    for &mode in &[
        SP_ERROR_SENTINEL,
        SP_ZERO,
        SP_OVERFLOW_CAP,
        SP_FILL_CAP,
        SP_TOO_LONG,
        SP_INVALID,
    ] {
        for &n in &[1024usize, 131072, 300_000, 512 * 1024] {
            for &level in &[1i32, 9, 19] {
                for &validate in &[0i32, 1] {
                    let mut per_fb: Vec<R> = Vec::new();
                    for &fallback in &[0i32, 1] {
                        let src = corpus(Corpus::LongRepeats, n, 0x5EED_0062);
                        let params = [
                            (ZSTD_c_compressionLevel, level),
                            (ZSTD_c_windowLog, 20),
                            (ZSTD_c_enableLongDistanceMatching, ZSTD_ps_disable),
                            (ZSTD_c_validateSequences, validate),
                            (ZSTD_c_enableSeqProducerFallback, fallback),
                        ];
                        let lbl = format!(
                            "spe/mode={mode}/n={n}/lvl={level}/v={validate}/fb={fallback}"
                        );
                        let (log, r, frame) = diff_bytes(&lbl, |l| {
                            drive_producer(l, Some(mode), &params, &src, false)
                        });
                        assert!(!log.is_empty(), "{lbl}: producer was never called");
                        if let R::Ok(_) = r {
                            diff_bytes(&format!("spe-dec/{lbl}"), |l| {
                                decompress_simple(l, &frame.0, n + 16)
                            });
                        }
                        per_fb.push(r);
                    }
                    // Semantic guard, so a suite that merely "agrees" cannot hide
                    // a fallback that never happens.
                    let tag = format!("mode={mode}/n={n}/lvl={level}/v={validate}");
                    match mode {
                        // Rejected by ZSTD_postProcessSequenceProducerResult:
                        // fallback is available and MUST rescue the compression.
                        SP_ERROR_SENTINEL | SP_ZERO | SP_OVERFLOW_CAP | SP_FILL_CAP => {
                            assert!(
                                matches!(per_fb[0], R::Err(106, _)),
                                "{tag}: fallback=0 must fail with sequenceProducer_failed, got {:?}",
                                per_fb[0]
                            );
                            assert!(
                                matches!(per_fb[1], R::Ok(_)),
                                "{tag}: fallback=1 must fall back to the internal match finder, got {:?}",
                                per_fb[1]
                            );
                        }
                        // Rejected AFTER post-processing succeeded (zstd_compress.c:3380
                        // / :3381), i.e. inside the `!ZSTD_isError` branch, where
                        // ZSTD_c_enableSeqProducerFallback has no effect at all.
                        SP_TOO_LONG => {
                            for (i, r) in per_fb.iter().enumerate() {
                                assert!(
                                    matches!(r, R::Err(107, _)),
                                    "{tag}: fb={i} must fail with externalSequences_invalid, got {r:?}"
                                );
                            }
                        }
                        SP_INVALID => {
                            let want_err = validate != 0;
                            for (i, r) in per_fb.iter().enumerate() {
                                assert_eq!(
                                    matches!(r, R::Err(107, _)),
                                    want_err,
                                    "{tag}: fb={i} unexpected outcome {r:?}"
                                );
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
    }
}

/// Registration mechanics.
///
/// * `ZSTD_registerSequenceProducer(cctx, st, NULL)` clears the registration
///   (zstd_compress.c:7830 takes the `else` branch and NULLs both fields), after
///   which the frame must be byte-identical to a plain `ZSTD_compress2`.
/// * `ZSTD_CCtxParams_registerSequenceProducer` +
///   `ZSTD_CCtx_setParametersUsingCCtxParams` must be equivalent to registering
///   on the CCtx directly, because the latter just copies the whole params
///   struct.
/// * `ZSTD_estimateCCtxSize_usingCCtxParams` grows by
///   `aligned64(ZSTD_sequenceBound(blockSize) * sizeof(ZSTD_Sequence))` once
///   `ZSTD_hasExtSeqProd` is true (CONFIGS row 143).
/// * a producer plus `ZSTD_c_enableLongDistanceMatching = ZSTD_ps_enable` is
///   `parameter_combination_unsupported` (41) at zstd_compress.c:3331
///   (CONFIGS row 142).
#[test]
fn t18_sequence_producer_registration() {
    let _sp_guard = sp_lock();
    covers(&["CFG:142-143", "ERR:compress/zstd_compress.c:3331"]);
    let src = corpus(Corpus::Text, 262_144, 0x5EED_0063);
    let base = |level: c_int| {
        [
            (ZSTD_c_compressionLevel, level),
            (ZSTD_c_windowLog, 20),
            (ZSTD_c_enableLongDistanceMatching, ZSTD_ps_disable),
        ]
    };

    // (a) NULL producer == no producer: identical to a plain compress2 frame.
    for &level in &[1i32, 3, 19] {
        let params = base(level);
        let cleared = diff_bytes(&format!("spnull/lvl={level}"), |l| {
            drive_producer(l, None, &params, &src, false)
        });
        assert!(cleared.0.is_empty(), "NULL producer must not be called");
        // Register a producer and then clear it again on the same CCtx.
        let reregistered = diff_bytes(&format!("spclear/lvl={level}"), |l| {
            sp_reset();
            let ctx = Ctx::cctx(l);
            let reg = l.sym::<FnRegisterSequenceProducer>("ZSTD_registerSequenceProducer");
            if let Some(e) = set_params(l, &ctx, &params) {
                return (sp_take(), e, Blob(Vec::new()));
            }
            unsafe { reg(ctx.ptr, SP_LITERALS_ONLY as *mut c_void, Some(seq_prod as SeqProdF)) };
            unsafe { reg(ctx.ptr, std::ptr::null_mut(), None) };
            let cap = compress_bound(l, src.len()).max(64);
            let mut dst = vec![0xCDu8; cap];
            let c2 = l.sym::<FnCompress2>("ZSTD_compress2");
            let n = unsafe {
                c2(
                    ctx.ptr,
                    dst.as_mut_ptr() as *mut c_void,
                    cap,
                    src.as_ptr() as *const c_void,
                    src.len(),
                )
            };
            let r = res(l, n);
            if let R::Ok(k) = r {
                dst.truncate(k);
            }
            (sp_take(), r, Blob(dst))
        });
        assert!(
            reregistered.0.is_empty(),
            "a cleared producer must not be called"
        );
        assert_eq!(
            cleared.1, reregistered.1,
            "clearing the producer must restore plain compression"
        );
        assert_eq!(
            cleared.2, reregistered.2,
            "clearing the producer must restore plain compression byte for byte"
        );
    }

    // (b) registration through ZSTD_CCtx_params.
    for &mode in &[SP_LITERALS_ONLY, SP_MANY_MATCHES, SP_ERROR_SENTINEL] {
        for &level in &[1i32, 12] {
            let params = base(level);
            let direct = diff_bytes(&format!("spdirect/mode={mode}/lvl={level}"), |l| {
                drive_producer(l, Some(mode), &params, &src, false)
            });
            let viap = diff_bytes(&format!("spviaparams/mode={mode}/lvl={level}"), |l| {
                drive_producer(l, Some(mode), &params, &src, true)
            });
            assert_eq!(
                direct, viap,
                "ZSTD_CCtxParams_registerSequenceProducer must match ZSTD_registerSequenceProducer (mode={mode}, level={level})"
            );
        }
    }

    // (c) ZSTD_estimateCCtxSize_usingCCtxParams with and without a producer.
    for &level in &[1i32, 3, 19] {
        for &wlog in &[10i32, 17, 20] {
            for &maxblock in &[0i32, 1024, 131072] {
                diff(&format!("spest/lvl={level}/wlog={wlog}/mb={maxblock}"), |l| {
                    let create = l.sym::<FnCreateCCtxParams>("ZSTD_createCCtxParams");
                    let free = l.sym::<FnFreeCCtxParams>("ZSTD_freeCCtxParams");
                    let setp = l.sym::<FnCCtxParamsSetParameter>("ZSTD_CCtxParams_setParameter");
                    let reg = l.sym::<FnRegisterSequenceProducer>(
                        "ZSTD_CCtxParams_registerSequenceProducer",
                    );
                    let est = l.sym::<FnEstimateCCtxSizeUsingCCtxParams>(
                        "ZSTD_estimateCCtxSize_usingCCtxParams",
                    );
                    let cp = unsafe { create() };
                    let mut sets = vec![
                        res(l, unsafe { setp(cp, ZSTD_c_compressionLevel, level) }),
                        res(l, unsafe { setp(cp, ZSTD_c_windowLog, wlog) }),
                    ];
                    if maxblock != 0 {
                        sets.push(res(l, unsafe { setp(cp, ZSTD_c_maxBlockSize, maxblock) }));
                    }
                    let without = res(l, unsafe { est(cp) });
                    unsafe { reg(cp, SP_LITERALS_ONLY as *mut c_void, Some(seq_prod as SeqProdF)) };
                    let with = res(l, unsafe { est(cp) });
                    unsafe { reg(cp, std::ptr::null_mut(), None) };
                    let cleared = res(l, unsafe { est(cp) });
                    unsafe { free(cp) };
                    (sets, without, with, cleared)
                });
            }
        }
    }

    // (d) producer + LDM enabled -> parameter_combination_unsupported.
    for &mode in &[SP_LITERALS_ONLY, SP_ERROR_SENTINEL] {
        for &ldm in &[ZSTD_ps_auto, ZSTD_ps_enable, ZSTD_ps_disable] {
            for &fallback in &[0i32, 1] {
                let params = [
                    (ZSTD_c_compressionLevel, 3),
                    (ZSTD_c_windowLog, 20),
                    (ZSTD_c_enableLongDistanceMatching, ldm),
                    (ZSTD_c_enableSeqProducerFallback, fallback),
                ];
                let (_, r, _) =
                    diff_bytes(&format!("spldm/mode={mode}/ldm={ldm}/fb={fallback}"), |l| {
                        drive_producer(l, Some(mode), &params, &src, false)
                    });
                if ldm == ZSTD_ps_enable {
                    // zstd_compress.c:3331 — an unconditional
                    // parameter_combination_unsupported (41) that
                    // ZSTD_c_enableSeqProducerFallback cannot rescue, because it
                    // fires before the producer is ever consulted.
                    assert!(
                        matches!(r, R::Err(41, _)),
                        "ldm=enable + producer must be parameter_combination_unsupported, got {r:?}"
                    );
                } else if mode == SP_LITERALS_ONLY {
                    assert!(
                        matches!(r, R::Ok(_)),
                        "ldm={ldm} + a well-behaved producer must succeed, got {r:?}"
                    );
                }
            }
        }
    }
}

// ===========================================================================
// Direct drive of the two exported helpers, and the remaining boundaries
// ===========================================================================

/// `BlockSummary` from `compress/zstd_compress_internal.h:1528`. Three `size_t`s,
/// i.e. 24 bytes, so on x86-64 SysV it is MEMORY class and returned through a
/// hidden pointer — worth exercising across the FFI boundary in its own right.
#[repr(C)]
#[derive(Copy, Clone, PartialEq, Eq)]
struct BlockSummary {
    nbSequences: SizeT,
    blockSize: SizeT,
    litSize: SizeT,
}
type FnGet1BlockSummary = unsafe extern "C" fn(*const ZSTD_Sequence, SizeT) -> BlockSummary;

/// `ZSTD_get1BlockSummary` (the scalar variant at zstd_compress.c:7448; the AVX2
/// variant at :7396 is not compiled because this build passes no `-mavx2`).
/// Scans until `matchLength == 0` and reports `nbSequences`, `blockSize` and
/// `litSize`; walking off the end sets `nbSequences = ERROR(externalSequences_invalid)`
/// (zstd_compress.c:7464).
#[test]
fn t19_get1_block_summary() {
    covers(&["CFG:209", "ERR:compress/zstd_compress.c:7464"]);
    let d = |ll: c_uint| ZSTD_Sequence { offset: 0, litLength: ll, matchLength: 0, rep: 0 };
    let s = |of: c_uint, ll: c_uint, ml: c_uint| ZSTD_Sequence {
        offset: of,
        litLength: ll,
        matchLength: ml,
        rep: 0,
    };
    let cases: Vec<(&str, Vec<ZSTD_Sequence>)> = vec![
        ("delim-only", vec![d(0)]),
        ("delim-ll7", vec![d(7)]),
        ("one-match", vec![s(1, 4, 8), d(3)]),
        ("two-matches", vec![s(1, 4, 8), s(2, 0, 5), d(0)]),
        ("no-delim", vec![s(1, 4, 8)]),
        ("no-delim-3", vec![s(1, 4, 8), s(2, 1, 9), s(3, 2, 10)]),
        // matchLength == 0 with a NON-zero offset still terminates the scan
        // (the `assert(seqs[n].offset == 0)` is compiled out at DEBUGLEVEL 0).
        ("ml0-of1", vec![s(1, 4, 0), d(0)]),
        ("two-blocks", vec![s(1, 4, 8), d(2), s(1, 4, 8), d(0)]),
        ("big-lengths", vec![s(1, 100_000, 131_072), d(11)]),
    ];
    for (name, v) in &cases {
        // Every prefix length, including 0 (which must report the error) and
        // lengths that stop before the delimiter.
        for k in 0..=v.len() {
            diff(&format!("bs/{name}/nbSeqs={k}"), |l| {
                let f = l.sym::<FnGet1BlockSummary>("ZSTD_get1BlockSummary");
                let bs = unsafe { f(v.as_ptr(), k) };
                let n = res(l, bs.nbSequences);
                // On the `n == nbSeqs` error path (zstd_compress.c:7461-7465) the
                // C builds `BlockSummary bs;` on the stack, sets ONLY
                // `bs.nbSequences = ERROR(externalSequences_invalid)` and returns
                // it — `blockSize` and `litSize` are left uninitialised, so their
                // values are indeterminate and must not be compared. (The C
                // observably returns leftover stack bytes there; the Rust returns
                // zeros. No caller ever reads them: every call site runs
                // `FORWARD_IF_ERROR(block.nbSequences, ...)` first.)
                match n {
                    R::Ok(_) => (n, Some((bs.blockSize, bs.litSize))),
                    R::Err(..) => (n, None),
                }
            });
        }
    }
}

/// `ZSTD_validateSequence`'s two bounds, probed exactly at the boundary
/// (CONFIGS rows 194 and 195).
///
/// * offset: `offsetBound = posInSrc > (1u<<windowLog) ? (1u<<windowLog)
///   : posInSrc + dictSize`, rejected when `offset > offsetBound`
///   (zstd_compress.c:6615). Both regimes are covered: a first block small
///   enough that `posInSrc <= windowSize`, and a second block after 128 KB have
///   already been described so that the `windowSize` clamp takes over.
/// * matchLength: `matchLenLowerBound = (minMatch == 3 || useSequenceProducer)
///   ? 3 : 4` (zstd_compress.c:6617), so `matchLength == 3` flips from valid to
///   invalid between `ZSTD_c_minMatch` 3 and 4.
///
/// Each case is run with `ZSTD_c_validateSequences` 1 and 0; with 0 the C must
/// instead produce a deterministic frame, which both libraries have to agree on
/// byte for byte.
#[test]
fn t20_validate_sequence_bounds() {
    covers(&[
        "CFG:194-195",
        "ERR:compress/zstd_compress.c:6615", "ERR:compress/zstd_compress.c:6617",
    ]);
    let src = corpus(Corpus::Text, 400_000, 0x5EED_0071);

    // --- offset bound, posInSrc regime (posInSrc <= windowSize) -------------
    for &wlog in &[17i32, 20] {
        let ll = 40u32;
        let ml = 60u32;
        let pos = (ll + ml) as usize; // posInSrc after the sequence
        for off in [
            pos as u32 - 2,
            pos as u32 - 1,
            pos as u32,
            pos as u32 + 1,
            pos as u32 + 2,
            1u32 << wlog,
            (1u32 << wlog) + 1,
        ] {
            for &validate in &[1i32, 0] {
                let seqs = vec![
                    ZSTD_Sequence { offset: off, litLength: ll, matchLength: ml, rep: 0 },
                    ZSTD_Sequence { offset: 0, litLength: 20, matchLength: 0, rep: 0 },
                ];
                let ssize = (ll + ml + 20) as usize;
                let params = [
                    (ZSTD_c_compressionLevel, 3),
                    (ZSTD_c_windowLog, wlog),
                    (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                    (ZSTD_c_validateSequences, validate),
                ];
                let cap = compress_bound(&pair().c, ssize).max(64);
                let lbl = format!("ofbound/wlog={wlog}/off={off}/pos={pos}/v={validate}");
                let (r, frame) = diff_bytes(&lbl, |l| {
                    compress_seqs(l, &params, &seqs, &src[..ssize], cap)
                });
                if let R::Ok(cs) = r {
                    diff_bytes(&format!("ofbound-dec/{lbl}"), |l| {
                        decompress_simple(l, &frame.0[..cs], ssize + 16)
                    });
                }
            }
        }
    }

    // --- offset bound, windowSize regime (posInSrc > windowSize) ------------
    // Block 1 is 128 KB of pure literals, so posInSrc == 131072 before block 2.
    for &wlog in &[17i32] {
        let wsize = 1usize << wlog;
        for off in [
            (wsize - 1) as u32,
            wsize as u32,
            (wsize + 1) as u32,
            (wsize + 2) as u32,
            (wsize * 2) as u32,
        ] {
            for &validate in &[1i32, 0] {
                let seqs = vec![
                    ZSTD_Sequence { offset: 0, litLength: 131_072, matchLength: 0, rep: 0 },
                    ZSTD_Sequence { offset: off, litLength: 40, matchLength: 60, rep: 0 },
                    ZSTD_Sequence { offset: 0, litLength: 20, matchLength: 0, rep: 0 },
                ];
                let ssize = 131_072 + 40 + 60 + 20;
                let params = [
                    (ZSTD_c_compressionLevel, 3),
                    (ZSTD_c_windowLog, wlog),
                    (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                    (ZSTD_c_validateSequences, validate),
                ];
                let cap = compress_bound(&pair().c, ssize).max(64);
                let lbl = format!("ofwin/wlog={wlog}/off={off}/v={validate}");
                let (r, frame) = diff_bytes(&lbl, |l| {
                    compress_seqs(l, &params, &seqs, &src[..ssize], cap)
                });
                if let R::Ok(cs) = r {
                    diff_bytes(&format!("ofwin-dec/{lbl}"), |l| {
                        decompress_simple(l, &frame.0[..cs], ssize + 16)
                    });
                }
            }
        }
    }

    // --- matchLength lower bound ------------------------------------------
    for mm in ZSTD_MINMATCH_MIN..=ZSTD_MINMATCH_MAX {
        for ml in 0u32..=8 {
            for &validate in &[1i32, 0] {
                for &delims in &[ZSTD_sf_explicitBlockDelimiters, ZSTD_sf_noBlockDelimiters] {
                    let mut seqs = vec![
                        ZSTD_Sequence { offset: 1, litLength: 8, matchLength: ml, rep: 0 },
                        ZSTD_Sequence { offset: 0, litLength: 12, matchLength: 0, rep: 0 },
                    ];
                    let ssize = (8 + ml + 12) as usize;
                    if delims == ZSTD_sf_noBlockDelimiters {
                        seqs.pop();
                    }
                    let params = [
                        (ZSTD_c_compressionLevel, 3),
                        (ZSTD_c_minMatch, mm),
                        (ZSTD_c_windowLog, 17),
                        (ZSTD_c_blockDelimiters, delims),
                        (ZSTD_c_validateSequences, validate),
                    ];
                    let cap = compress_bound(&pair().c, ssize).max(64);
                    let lbl = format!("mlbound/mm={mm}/ml={ml}/v={validate}/d={delims}");
                    let (r, frame) = diff_bytes(&lbl, |l| {
                        compress_seqs(l, &params, &seqs, &src[..ssize], cap)
                    });
                    if let R::Ok(cs) = r {
                        diff_bytes(&format!("mlbound-dec/{lbl}"), |l| {
                            decompress_simple(l, &frame.0[..cs], ssize + 16)
                        });
                    }
                }
            }
        }
    }
}

/// The remaining two odds and ends.
///
/// (a) `ZSTD_generateSequences`'s allocation failure (zstd_compress.c:3538): the
/// scratch buffer is `ZSTD_customMalloc(ZSTD_compressBound(srcSize))`, and for
/// `srcSize >= ZSTD_MAX_INPUT_SIZE` (0xFF00FF00FF00FF00) `ZSTD_compressBound`
/// itself returns `ERROR(srcSize_wrong)` == `(size_t)-72`, which is then handed
/// to `malloc` as a ~1.8e19-byte request.  glibc refuses anything above
/// `PTRDIFF_MAX` outright, so the call returns `memory_allocation` (64) WITHOUT
/// ever dereferencing `src` — verified empirically before this case was added,
/// which is why passing a bogus `srcSize` next to a 64-byte buffer is safe here.
///
/// (b) `ZSTD_CCtxParams_registerSequenceProducer` +
/// `ZSTD_estimateCCtxSize_usingCCtxParams` + `ZSTD_initStaticCCtx`
/// (CONFIGS row 143): `ZSTD_hasExtSeqProd` adds
/// `aligned64(ZSTD_sequenceBound(blockSize) * sizeof(ZSTD_Sequence))` to the
/// estimate, so a workspace sized WITHOUT the producer must be too small once it
/// is registered, and one sized WITH it must suffice.
#[test]
fn t21_misc_allocation_and_static_cctx() {
    let _sp_guard = sp_lock();
    covers(&[
        "CFG:143",
        "ERR:compress/zstd_compress.c:3538", "ERR:compress/zstd_compress.c:3549",
    ]);
    // (a)
    let tiny = vec![0u8; 64];
    for &n in &[
        0xFF00FF00FF00FF00usize,
        0xFF00FF00FF00FF01,
        0xFF00FF00FF00FEFF,
        usize::MAX,
    ] {
        diff(&format!("genhuge/n=0x{n:x}"), |l| {
            let ctx = Ctx::cctx(l);
            let mut out = vec![ZSTD_Sequence::default(); 16];
            let f = l.sym::<FnGenerateSequences>("ZSTD_generateSequences");
            let rc = unsafe {
                f(ctx.ptr, out.as_mut_ptr(), 16, tiny.as_ptr() as *const c_void, n)
            };
            (res(l, rc), Seqs(out))
        });
    }

    // (b)
    let src = corpus(Corpus::Text, 262_144, 0x5EED_0072);
    for &mode in &[SP_LITERALS_ONLY, SP_MANY_MATCHES] {
        for &level in &[1i32, 12] {
            for with_prod_in_estimate in [true, false] {
                let lbl = format!("static/mode={mode}/lvl={level}/est={with_prod_in_estimate}");
                diff_bytes(&lbl, |l| {
                    sp_reset();
                    let create = l.sym::<FnCreateCCtxParams>("ZSTD_createCCtxParams");
                    let free = l.sym::<FnFreeCCtxParams>("ZSTD_freeCCtxParams");
                    let setp = l.sym::<FnCCtxParamsSetParameter>("ZSTD_CCtxParams_setParameter");
                    let regp = l.sym::<FnRegisterSequenceProducer>(
                        "ZSTD_CCtxParams_registerSequenceProducer",
                    );
                    let regc =
                        l.sym::<FnRegisterSequenceProducer>("ZSTD_registerSequenceProducer");
                    let est = l.sym::<FnEstimateCCtxSizeUsingCCtxParams>(
                        "ZSTD_estimateCCtxSize_usingCCtxParams",
                    );
                    let init_static = l
                        .sym::<unsafe extern "C" fn(*mut c_void, SizeT) -> *mut c_void>(
                            "ZSTD_initStaticCCtx",
                        );
                    let apply =
                        l.sym::<FnSetParamsUsingCCtxParams>("ZSTD_CCtx_setParametersUsingCCtxParams");

                    let cp = unsafe { create() };
                    let mut sets = vec![
                        res(l, unsafe { setp(cp, ZSTD_c_compressionLevel, level) }),
                        res(l, unsafe { setp(cp, ZSTD_c_windowLog, 20) }),
                        res(l, unsafe {
                            setp(cp, ZSTD_c_enableLongDistanceMatching, ZSTD_ps_disable)
                        }),
                    ];
                    if with_prod_in_estimate {
                        unsafe { regp(cp, mode as *mut c_void, Some(seq_prod as SeqProdF)) };
                    }
                    let need = unsafe { est(cp) };
                    sets.push(res(l, need));
                    if is_error(l, need) {
                        unsafe { free(cp) };
                        return (sets, R::Ok(usize::MAX), Blob(Vec::new()));
                    }
                    // 8-aligned workspace, as ZSTD_initStaticCCtx demands.
                    let mut ws = vec![0u64; need / 8 + 2];
                    let cctx = unsafe {
                        init_static(ws.as_mut_ptr() as *mut c_void, ws.len() * 8)
                    };
                    if cctx.is_null() {
                        unsafe { free(cp) };
                        return (sets, R::Ok(usize::MAX - 1), Blob(Vec::new()));
                    }
                    // Always register the producer on the CCtx itself, so the
                    // `est == false` variant is the deliberately-undersized case.
                    if !with_prod_in_estimate {
                        unsafe { regp(cp, mode as *mut c_void, Some(seq_prod as SeqProdF)) };
                    }
                    sets.push(res(l, unsafe { apply(cctx, cp) }));
                    unsafe { regc(cctx, mode as *mut c_void, Some(seq_prod as SeqProdF)) };
                    unsafe { free(cp) };

                    let cap = compress_bound(l, src.len()).max(64);
                    let mut dst = vec![0xCDu8; cap];
                    let c2 = l.sym::<FnCompress2>("ZSTD_compress2");
                    let rc = unsafe {
                        c2(
                            cctx,
                            dst.as_mut_ptr() as *mut c_void,
                            cap,
                            src.as_ptr() as *const c_void,
                            src.len(),
                        )
                    };
                    let r = res(l, rc);
                    if let R::Ok(k) = r {
                        dst.truncate(k);
                    } else {
                        dst.truncate(0);
                    }
                    (sets, r, Blob(dst))
                });
            }
        }
    }
}

/// The last few named branches that the generator-derived fixtures do not reach
/// on their own.
///
/// (a) `cannotProduce_uncompressedBlock` (49) at zstd_compress.c:7550
///     (CONFIGS row 207): a block made ONLY of incompressible literals.  The
///     entropy coder cannot shrink it and `ZSTD_compressSequencesAndLiterals` has
///     no source buffer to fall back on, so unlike `ZSTD_compressSequences` it
///     cannot emit a raw block.
/// (b) the three-way repcode back-patch of `ZSTD_transferSequences_wBlockDelim`
///     under `ZSTD_c_repcodeResolution == ZSTD_ps_disable`
///     (zstd_compress.c:6702-6720): the `lastSeqIdx >= startIdx+2`,
///     `== startIdx+1` and `== startIdx` arms need blocks holding exactly 3+, 2
///     and 1 non-delimiter sequences respectively, and the state carries into the
///     NEXT block, so the effect is only visible in a multi-block stream.
///     Levels 9 and 10 straddle `ZSTD_resolveExternalRepcodeSearch`'s auto rule.
/// (c) `determine_blockSize`'s "too large block" message (zstd_compress.c:6932)
///     driven by `ZSTD_c_maxBlockSize` rather than by ZSTD_BLOCKSIZE_MAX
///     (CONFIGS row 192).
#[test]
fn t22_remaining_named_branches() {
    covers(&[
        "CFG:192",
        "CFG:198",
        "CFG:207",
        "ERR:compress/zstd_compress.c:6932", "ERR:compress/zstd_compress.c:7550",
    ]);

    // ---- (a) incompressible literals ------------------------------------
    let params = [
        (ZSTD_c_compressionLevel, 1),
        (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
    ];
    for &n in &[16usize, 1024, 65536, 131_072] {
        let mut lits = corpus(Corpus::Random, n, 0x5EED_0081);
        lits.extend_from_slice(&[0u8; 8]);
        let seqs = vec![ZSTD_Sequence {
            offset: 0,
            litLength: n as c_uint,
            matchLength: 0,
            rep: 0,
        }];
        let cap = compress_bound(&pair().c, n).max(64);
        let r = diff_bytes(&format!("nocomp/n={n}"), |l| {
            compress_seqs_lits(l, &params, &seqs, &lits, n, n + 8, n, cap)
        })
        .0;
        if n >= 1024 {
            assert_eq!(
                r,
                R::Err(49, "This mode cannot generate an uncompressed block".to_string()),
                "n={n}: expected cannotProduce_uncompressedBlock"
            );
        }
    }

    // ---- (b) the repcode back-patch arms --------------------------------
    // A multi-block stream in which consecutive blocks hold 3, 2, 1 and 0
    // non-delimiter sequences, all reusing the same handful of offsets so the
    // repcode machinery has something to find.
    let src = corpus(Corpus::Periodic, 4 * 64 + 40, 0x5EED_0082);
    let s = |of: c_uint, ll: c_uint, ml: c_uint| ZSTD_Sequence {
        offset: of,
        litLength: ll,
        matchLength: ml,
        rep: 0,
    };
    let dl = |ll: c_uint| ZSTD_Sequence { offset: 0, litLength: ll, matchLength: 0, rep: 0 };
    // Each block is 64 bytes: 3 x (ll 8 + ml 8) = 48 plus 16 last literals, etc.
    let stream: Vec<ZSTD_Sequence> = vec![
        // block 1: three sequences (lastSeqIdx >= startIdx + 2)
        s(4, 8, 8),
        s(4, 8, 8),
        s(8, 8, 8),
        dl(16),
        // block 2: two sequences (lastSeqIdx == startIdx + 1)
        s(4, 8, 8),
        s(12, 8, 8),
        dl(32),
        // block 3: one sequence (lastSeqIdx == startIdx)
        s(4, 8, 8),
        dl(48),
        // block 4: no sequence at all (idx == startIdx, the loop never runs)
        dl(64),
        // block 5: the remaining 40 bytes, one sequence again
        s(4, 8, 8),
        dl(24),
    ];
    for &level in &[9i32, 10] {
        for &repres in &[ZSTD_ps_auto, ZSTD_ps_enable, ZSTD_ps_disable] {
            for &maxblock in &[1024i32, 64] {
                let p = [
                    (ZSTD_c_compressionLevel, level),
                    (ZSTD_c_maxBlockSize, maxblock),
                    (ZSTD_c_windowLog, 17),
                    (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                    (ZSTD_c_repcodeResolution, repres),
                    (ZSTD_c_validateSequences, 1),
                ];
                let cap = compress_bound(&pair().c, src.len()).max(64);
                let lbl = format!("repfix/lvl={level}/r={repres}/mb={maxblock}");
                let (r, frame) =
                    diff_bytes(&lbl, |l| compress_seqs(l, &p, &stream, &src, cap));
                if let R::Ok(cs) = r {
                    diff_bytes(&format!("repfix-dec/{lbl}"), |l| {
                        decompress_simple(l, &frame.0[..cs], src.len() + 16)
                    });
                }
            }
        }
    }

    // ---- (c) ZSTD_c_maxBlockSize-driven "too large block" ----------------
    let big = corpus(Corpus::Text, 8192, 0x5EED_0083);
    for &maxblock in &[1024i32, 2048, 4096] {
        for &blk in &[1000usize, 1024, 1025, 2048, 4096] {
            let seqs = vec![
                ZSTD_Sequence { offset: 1, litLength: 8, matchLength: (blk - 8) as c_uint, rep: 0 },
                ZSTD_Sequence::default(),
            ];
            let p = [
                (ZSTD_c_compressionLevel, 3),
                (ZSTD_c_maxBlockSize, maxblock),
                (ZSTD_c_windowLog, 17),
                (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                (ZSTD_c_validateSequences, 1),
            ];
            let cap = compress_bound(&pair().c, blk).max(64);
            let lbl = format!("mbsize/mb={maxblock}/blk={blk}");
            let (r, frame) =
                diff_bytes(&lbl, |l| compress_seqs(l, &p, &seqs, &big[..blk], cap));
            if let R::Ok(cs) = r {
                diff_bytes(&format!("mbsize-dec/{lbl}"), |l| {
                    decompress_simple(l, &frame.0[..cs], blk + 16)
                });
            }
        }
    }
}

/// `ZSTD_c_splitAfterSequences` interacting with `ZSTD_generateSequences`.
///
/// With the post-block splitter enabled the collecting path runs through
/// `ZSTD_compressBlock_splitBlock` instead of `ZSTD_compressBlock_internal`, and
/// the `ZSTDbss_noCompress` guard is a SECOND, separate copy of the same
/// `RETURN_ERROR_IF(zc->seqCollector.collectSequences, sequenceProducer_failed,
/// "Uncompressible block")` at zstd_compress.c:4368 (the first is at :4402).
/// `srcSize == 6` (< `MIN_CBLOCK_SIZE+ZSTD_blockHeaderSize+1+1` == 7) is the
/// shortest way to reach either.
#[test]
fn t23_generate_sequences_split_after_sequences() {
    covers(&[
        "CFG:186",
        "ERR:compress/zstd_compress.c:4368", "ERR:compress/zstd_compress.c:4402",
        "ERR:compress/zstd_compress.c:4210", "ERR:compress/zstd_compress.c:4244",
    ]);
    for &split in &[ZSTD_ps_auto, ZSTD_ps_enable, ZSTD_ps_disable] {
        for &level in &[1i32, 3, 19] {
            for &kind in &[Corpus::Text, Corpus::Zeros, Corpus::Random, Corpus::LongRepeats] {
                for &n in &[0usize, 1, 6, 7, 8, 100, 8192, 131_072, 131_073, 300_000] {
                    let src = corpus(kind, n, 0x5EED_0091);
                    let cap = seq_bound(&pair().c, n);
                    let params = [
                        (ZSTD_c_compressionLevel, level),
                        (ZSTD_c_splitAfterSequences, split),
                    ];
                    diff(
                        &format!("gensplit/s={split}/lvl={level}/{kind:?}/n={n}"),
                        |l| gen_seqs(l, &params, &src, cap),
                    );
                }
            }
        }
    }
}

type FnLoadDictionary = unsafe extern "C" fn(*mut c_void, *const c_void, SizeT) -> SizeT;
type FnLoadDictionaryAdvanced =
    unsafe extern "C" fn(*mut c_void, *const c_void, SizeT, c_int, c_int) -> SizeT;
type FnRefPrefix = unsafe extern "C" fn(*mut c_void, *const c_void, SizeT) -> SizeT;

/// The dictionary interaction of `ZSTD_compressSequences`.
///
/// (a) `ZSTD_validateSequence` computes
///     `offsetBound = posInSrc > windowSize ? windowSize : posInSrc + dictSize`
///     (zstd_compress.c:6612), and `ZSTD_transferSequences_wBlockDelim` sources
///     `dictSize` from `cctx->cdict->dictContentSize` or
///     `cctx->prefixDict.dictSize` (zstd_compress.c:6661-6666).  So an offset
///     that is rejected without a dictionary must be ACCEPTED once a dictionary
///     of the right size is attached — the second half of CONFIGS row 194.
///
/// (b) `ZSTD_compressSequences` forwards a failing
///     `ZSTD_CCtx_init_compressStream2` (zstd_compress.c:7074, forwarded from
///     :6422), which a `ZSTD_dct_fullDict` load of a buffer that merely *starts*
///     with `ZSTD_MAGIC_DICTIONARY` triggers.
#[test]
fn t24_compress_sequences_with_dictionary() {
    covers(&[
        "CFG:194",
        "ERR:compress/zstd_compress.c:7074", "ERR:compress/zstd_compress.c:6422",
        "ERR:compress/zstd_compress.c:6615",
    ]);
    let src = corpus(Corpus::Text, 4096, 0x5EED_00A1);

    // (a) a raw-content dictionary widens the offset bound by exactly dictSize.
    for &dict_size in &[0usize, 16, 1024, 4096] {
        let dict = corpus(Corpus::Counter, dict_size, 0x5EED_00A2);
        let ll = 40u32;
        let ml = 60u32;
        let pos = (ll + ml) as usize;
        for off in [
            pos as u32,
            (pos + dict_size) as u32,
            (pos + dict_size) as u32 + 1,
            (pos + dict_size) as u32 + 2,
        ] {
            for &by_prefix in &[false, true] {
                let seqs = vec![
                    ZSTD_Sequence { offset: off, litLength: ll, matchLength: ml, rep: 0 },
                    ZSTD_Sequence { offset: 0, litLength: 20, matchLength: 0, rep: 0 },
                ];
                let ssize = (ll + ml + 20) as usize;
                let lbl =
                    format!("csdict/dsz={dict_size}/off={off}/prefix={by_prefix}");
                diff_bytes(&lbl, |l| {
                    let ctx = Ctx::cctx(l);
                    let params = [
                        (ZSTD_c_compressionLevel, 3),
                        (ZSTD_c_windowLog, 17),
                        (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                        (ZSTD_c_validateSequences, 1),
                    ];
                    if let Some(e) = set_params(l, &ctx, &params) {
                        return (e, Blob(Vec::new()));
                    }
                    let lr = if dict_size == 0 {
                        R::Ok(0)
                    } else if by_prefix {
                        let f = l.sym::<FnRefPrefix>("ZSTD_CCtx_refPrefix");
                        res(l, unsafe {
                            f(ctx.ptr, dict.as_ptr() as *const c_void, dict_size)
                        })
                    } else {
                        let f = l.sym::<FnLoadDictionaryAdvanced>(
                            "ZSTD_CCtx_loadDictionary_advanced",
                        );
                        res(l, unsafe {
                            f(
                                ctx.ptr,
                                dict.as_ptr() as *const c_void,
                                dict_size,
                                ZSTD_dlm_byRef,
                                ZSTD_dct_rawContent,
                            )
                        })
                    };
                    if let R::Err(..) = lr {
                        return (lr, Blob(Vec::new()));
                    }
                    let cap = compress_bound(l, ssize).max(64);
                    let mut dst = vec![0xCDu8; cap];
                    let f = l.sym::<FnCompressSequences>("ZSTD_compressSequences");
                    let n = unsafe {
                        f(
                            ctx.ptr,
                            dst.as_mut_ptr() as *mut c_void,
                            cap,
                            seqs.as_ptr(),
                            seqs.len(),
                            src.as_ptr() as *const c_void,
                            ssize,
                        )
                    };
                    (res(l, n), Blob(dst))
                });
            }
        }
    }

    // (b) a corrupt ZSTD_dct_fullDict dictionary must abort the whole call.
    let mut bad = Vec::new();
    bad.extend_from_slice(&ZSTD_MAGIC_DICTIONARY.to_le_bytes());
    bad.extend_from_slice(&[0xFFu8; 12]);
    let seqs = vec![
        ZSTD_Sequence { offset: 1, litLength: 8, matchLength: 8, rep: 0 },
        ZSTD_Sequence { offset: 0, litLength: 8, matchLength: 0, rep: 0 },
    ];
    for &dsz in &[4usize, 8, 12, 16] {
        for &dct in &[ZSTD_dct_auto, ZSTD_dct_fullDict] {
            let lbl = format!("csbaddict/dsz={dsz}/dct={dct}");
            diff_bytes(&lbl, |l| {
                let ctx = Ctx::cctx(l);
                let params = [
                    (ZSTD_c_compressionLevel, 3),
                    (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
                ];
                if let Some(e) = set_params(l, &ctx, &params) {
                    return (e.clone(), e, Blob(Vec::new()));
                }
                let f =
                    l.sym::<FnLoadDictionaryAdvanced>("ZSTD_CCtx_loadDictionary_advanced");
                let lr = res(l, unsafe {
                    f(ctx.ptr, bad.as_ptr() as *const c_void, dsz, ZSTD_dlm_byRef, dct)
                });
                let cap = compress_bound(l, 24).max(64);
                let mut dst = vec![0xCDu8; cap];
                let g = l.sym::<FnCompressSequences>("ZSTD_compressSequences");
                let n = unsafe {
                    g(
                        ctx.ptr,
                        dst.as_mut_ptr() as *mut c_void,
                        cap,
                        seqs.as_ptr(),
                        seqs.len(),
                        src.as_ptr() as *const c_void,
                        24,
                    )
                };
                (lr, res(l, n), Blob(dst))
            });
        }
    }

    // and the same through ZSTD_CCtx_loadDictionary (byCopy, auto).
    for &dsz in &[4usize, 16] {
        diff_bytes(&format!("csbaddict2/dsz={dsz}"), |l| {
            let ctx = Ctx::cctx(l);
            let params = [
                (ZSTD_c_compressionLevel, 3),
                (ZSTD_c_blockDelimiters, ZSTD_sf_explicitBlockDelimiters),
            ];
            if let Some(e) = set_params(l, &ctx, &params) {
                return (e.clone(), e, Blob(Vec::new()));
            }
            let f = l.sym::<FnLoadDictionary>("ZSTD_CCtx_loadDictionary");
            let lr = res(l, unsafe {
                f(ctx.ptr, bad.as_ptr() as *const c_void, dsz)
            });
            let cap = compress_bound(l, 24).max(64);
            let mut dst = vec![0xCDu8; cap];
            let g = l.sym::<FnCompressSequences>("ZSTD_compressSequences");
            let n = unsafe {
                g(
                    ctx.ptr,
                    dst.as_mut_ptr() as *mut c_void,
                    cap,
                    seqs.as_ptr(),
                    seqs.len(),
                    src.as_ptr() as *const c_void,
                    24,
                )
            };
            (lr, res(l, n), Blob(dst))
        });
    }
}
